    Condition.add_member(:crawl_state, Smithy::Schema::Shapes::ShapeRef.new(shape: CrawlState, location_name: 'CrawlState', traits: {"smithy.api#documentation" => "<p>The state of the crawler to which this condition applies.</p>"}))
