    ConfusionMatrix.add_member(:num_true_positives, Smithy::Schema::Shapes::ShapeRef.new(shape: RecordsCount, location_name: 'NumTruePositives', traits: {"smithy.api#documentation" => "<p>The number of matches in the data that the transform correctly found, in the confusion matrix for your transform.</p>"}))
    ConfusionMatrix.add_member(:num_false_positives, Smithy::Schema::Shapes::ShapeRef.new(shape: RecordsCount, location_name: 'NumFalsePositives', traits: {"smithy.api#documentation" => "<p>The number of nonmatches in the data that the transform incorrectly classified as a match,\n      in the confusion matrix for your transform.</p>"}))
