    ConfusionMatrix.add_member(:num_false_negatives, Smithy::Schema::Shapes::ShapeRef.new(shape: RecordsCount, location_name: 'NumFalseNegatives', traits: {"smithy.api#documentation" => "<p>The number of matches in the data that the transform didn't find, in the confusion matrix for your transform.</p>"}))
