    CreateIntegrationTablePropertiesRequest.type = Types::CreateIntegrationTablePropertiesRequest
    CreateIntegrationTablePropertiesResponse.type = Types::CreateIntegrationTablePropertiesResponse
    CreateJobRequest.add_member(:name, Smithy::Schema::Shapes::ShapeRef.new(shape: NameString, location_name: 'Name', traits: {"smithy.api#documentation" => "<p>The name you assign to this job definition. It must be unique in your account.</p>", "smithy.api#required" => {}}))
    CreateJobRequest.add_member(:job_mode, Smithy::Schema::Shapes::ShapeRef.new(shape: JobMode, location_name: 'JobMode', traits: {"smithy.api#documentation" => "<p>A mode that describes how a job was created. Valid values are:</p>\n         <ul>\n            <li>\n               <p>\n                  <code>SCRIPT</code> - The job was created using the Glue Studio script editor.</p>\n            </li>\n            <li>\n               <p>\n                  <code>VISUAL</code> - The job was created using the Glue Studio visual editor.</p>\n            </li>\n            <li>\n               <p>\n                  <code>NOTEBOOK</code> - The job was created using an interactive sessions notebook.</p>\n            </li>\n         </ul>\n         <p>When the <code>JobMode</code> field is missing or null, <code>SCRIPT</code> is assigned as the default value.</p>"}))
    CreateJobRequest.add_member(:job_run_queuing_enabled, Smithy::Schema::Shapes::ShapeRef.new(shape: NullableBoolean, location_name: 'JobRunQueuingEnabled', traits: {"smithy.api#documentation" => "<p>Specifies whether job run queuing is enabled for the job runs for this job.</p>\n         <p>A value of true means job run queuing is enabled for the job runs. If false or not populated, the job runs will not be considered for queueing.</p>\n         <p>If this field does not match the value set in the job run, then the value from the job run field will be used.</p>"}))
    CreateJobRequest.add_member(:description, Smithy::Schema::Shapes::ShapeRef.new(shape: DescriptionString, location_name: 'Description', traits: {"smithy.api#documentation" => "<p>Description of the job being defined.</p>"}))
    CreateJobRequest.add_member(:log_uri, Smithy::Schema::Shapes::ShapeRef.new(shape: UriString, location_name: 'LogUri', traits: {"smithy.api#documentation" => "<p>This field is reserved for future use.</p>"}))
    CreateJobRequest.add_member(:role, Smithy::Schema::Shapes::ShapeRef.new(shape: RoleString, location_name: 'Role', traits: {"smithy.api#documentation" => "<p>The name or Amazon Resource Name (ARN) of the IAM role associated with this job.</p>", "smithy.api#required" => {}}))
    CreateJobRequest.add_member(:execution_property, Smithy::Schema::Shapes::ShapeRef.new(shape: ExecutionProperty, location_name: 'ExecutionProperty', traits: {"smithy.api#documentation" => "<p>An <code>ExecutionProperty</code> specifying the maximum number of concurrent runs allowed\n      for this job.</p>"}))
    CreateJobRequest.add_member(:command, Smithy::Schema::Shapes::ShapeRef.new(shape: JobCommand, location_name: 'Command', traits: {"smithy.api#documentation" => "<p>The <code>JobCommand</code> that runs this job.</p>", "smithy.api#required" => {}}))
    CreateJobRequest.add_member(:default_arguments, Smithy::Schema::Shapes::ShapeRef.new(shape: GenericMap, location_name: 'DefaultArguments', traits: {"smithy.api#documentation" => "<p>The default arguments for every run of this job, specified as name-value pairs.</p>\n         <p>You can specify arguments here that your own job-execution script\n      consumes, as well as arguments that Glue itself consumes.</p>\n         <p>Job arguments may be logged. Do not pass plaintext secrets as arguments. Retrieve secrets\n      from a Glue Connection, Secrets Manager or other secret management\n      mechanism if you intend to keep them within the Job. </p>\n         <p>For information about how to specify and consume your own Job arguments, see the <a href=\"https://docs.aws.amazon.com/glue/latest/dg/aws-glue-programming-python-calling.html\">Calling Glue APIs in Python</a> topic in the developer guide.</p>\n         <p>For information about the arguments you can provide to this field when configuring Spark jobs,\n     see the <a href=\"https://docs.aws.amazon.com/glue/latest/dg/aws-glue-programming-etl-glue-arguments.html\">Special Parameters Used by Glue</a> topic in the developer guide.</p>\n         <p>For information about the arguments you can provide to this field when configuring Ray\n      jobs, see <a href=\"https://docs.aws.amazon.com/glue/latest/dg/author-job-ray-job-parameters.html\">Using\n      job parameters in Ray jobs</a> in the developer guide.</p>"}))
    CreateJobRequest.add_member(:non_overridable_arguments, Smithy::Schema::Shapes::ShapeRef.new(shape: GenericMap, location_name: 'NonOverridableArguments', traits: {"smithy.api#documentation" => "<p>Arguments for this job that are not overridden when providing job arguments\n      in a job run, specified as name-value pairs.</p>"}))
    CreateJobRequest.add_member(:connections, Smithy::Schema::Shapes::ShapeRef.new(shape: ConnectionsList, location_name: 'Connections', traits: {"smithy.api#documentation" => "<p>The connections used for this job.</p>"}))
    CreateJobRequest.add_member(:max_retries, Smithy::Schema::Shapes::ShapeRef.new(shape: MaxRetries, location_name: 'MaxRetries', traits: {"smithy.api#default" => 0, "smithy.api#documentation" => "<p>The maximum number of times to retry this job if it fails.</p>"}))
    CreateJobRequest.add_member(:allocated_capacity, Smithy::Schema::Shapes::ShapeRef.new(shape: IntegerValue, location_name: 'AllocatedCapacity', traits: {"smithy.api#default" => 0, "smithy.api#deprecated" => {"message" => "This property is deprecated, use MaxCapacity instead."}, "smithy.api#documentation" => "<p>This parameter is deprecated. Use <code>MaxCapacity</code> instead.</p>\n         <p>The number of Glue data processing units (DPUs) to allocate to this Job. You can\n      allocate a minimum of 2 DPUs; the default is 10. A DPU is a relative measure of processing\n      power that consists of 4 vCPUs of compute capacity and 16 GB of memory. For more information,\n      see the <a href=\"https://aws.amazon.com/glue/pricing/\">Glue pricing\n      page</a>.</p>"}))
    CreateJobRequest.add_member(:timeout, Smithy::Schema::Shapes::ShapeRef.new(shape: Timeout, location_name: 'Timeout', traits: {"smithy.api#documentation" => "<p>The job timeout in minutes.  This is the maximum time that a job run\n      can consume resources before it is terminated and enters <code>TIMEOUT</code>\n      status.</p>\n         <p>Jobs must have timeout values less than 7 days or 10080 minutes. Otherwise, the jobs will throw an exception.</p>\n         <p>When the value is left blank, the timeout is defaulted to 2880 minutes.</p>\n         <p>Any existing Glue jobs that had a timeout value greater than 7 days will be defaulted to 7 days. For instance if you have specified a timeout of 20 days for a batch job, it will be stopped on the 7th day.</p>\n         <p>For streaming jobs, if you have set up a maintenance window, it will be restarted during the maintenance window after 7 days.</p>"}))
    CreateJobRequest.add_member(:max_capacity, Smithy::Schema::Shapes::ShapeRef.new(shape: NullableDouble, location_name: 'MaxCapacity', traits: {"smithy.api#documentation" => "<p>For Glue version 1.0 or earlier jobs, using the standard worker type, the number of\n      Glue data processing units (DPUs) that can be allocated when this job runs. A DPU is\n      a relative measure of processing power that consists of 4 vCPUs of compute capacity and 16 GB\n      of memory. For more information, see the <a href=\"https://aws.amazon.com/glue/pricing/\">\n      Glue pricing page</a>.</p>\n         <p>For Glue version 2.0+ jobs, you cannot specify a <code>Maximum capacity</code>.\n      Instead, you should specify a <code>Worker type</code> and the <code>Number of workers</code>.</p>\n         <p>Do not set <code>MaxCapacity</code> if using <code>WorkerType</code> and <code>NumberOfWorkers</code>.</p>\n         <p>The value that can be allocated for <code>MaxCapacity</code> depends on whether you are\n      running a Python shell job, an Apache Spark ETL job, or an Apache Spark streaming ETL\n      job:</p>\n         <ul>\n            <li>\n               <p>When you specify a Python shell job (<code>JobCommand.Name</code>=\"pythonshell\"), you can\n          allocate either 0.0625 or 1 DPU. The default is 0.0625 DPU.</p>\n            </li>\n            <li>\n               <p>When you specify an Apache Spark ETL job (<code>JobCommand.Name</code>=\"glueetl\") or Apache \n        Spark streaming ETL job (<code>JobCommand.Name</code>=\"gluestreaming\"), you can allocate from 2 to 100 DPUs. \n        The default is 10 DPUs. This job type cannot have a fractional DPU allocation.</p>\n            </li>\n         </ul>"}))
    CreateJobRequest.add_member(:security_configuration, Smithy::Schema::Shapes::ShapeRef.new(shape: NameString, location_name: 'SecurityConfiguration', traits: {"smithy.api#documentation" => "<p>The name of the <code>SecurityConfiguration</code> structure to be used with this\n      job.</p>"}))
    CreateJobRequest.add_member(:tags, Smithy::Schema::Shapes::ShapeRef.new(shape: TagsMap, location_name: 'Tags', traits: {"smithy.api#documentation" => "<p>The tags to use with this job. You may use tags to limit access to the job. For more information about tags in Glue, see <a href=\"https://docs.aws.amazon.com/glue/latest/dg/monitor-tags.html\">Amazon Web Services Tags in Glue</a> in the developer guide.</p>"}))
    CreateJobRequest.add_member(:notification_property, Smithy::Schema::Shapes::ShapeRef.new(shape: NotificationProperty, location_name: 'NotificationProperty', traits: {"smithy.api#documentation" => "<p>Specifies configuration properties of a job notification.</p>"}))
    CreateJobRequest.add_member(:glue_version, Smithy::Schema::Shapes::ShapeRef.new(shape: GlueVersionString, location_name: 'GlueVersion', traits: {"smithy.api#documentation" => "<p>In Spark jobs, <code>GlueVersion</code> determines the versions of Apache Spark and Python\n      that Glue available in a job. The Python version indicates the version\n      supported for jobs of type Spark. </p>\n         <p>Ray jobs should set <code>GlueVersion</code> to <code>4.0</code> or greater. However,\n    the versions of Ray, Python and additional libraries available in your Ray job are determined\n    by the <code>Runtime</code> parameter of the Job command.</p>\n         <p>For more information about the available Glue versions and corresponding\n      Spark and Python versions, see <a href=\"https://docs.aws.amazon.com/glue/latest/dg/add-job.html\">Glue version</a> in the developer\n      guide.</p>\n         <p>Jobs that are created without specifying a Glue version default to Glue 0.9.</p>"}))
    CreateJobRequest.add_member(:number_of_workers, Smithy::Schema::Shapes::ShapeRef.new(shape: NullableInteger, location_name: 'NumberOfWorkers', traits: {"smithy.api#documentation" => "<p>The number of workers of a defined <code>workerType</code> that are allocated when a job runs.</p>"}))
    CreateJobRequest.add_member(:worker_type, Smithy::Schema::Shapes::ShapeRef.new(shape: WorkerType, location_name: 'WorkerType', traits: {"smithy.api#documentation" => "<p>The type of predefined worker that is allocated when a job runs. Accepts a value of\n      G.1X, G.2X, G.4X, G.8X or G.025X for Spark jobs. Accepts the value Z.2X for Ray jobs.</p>\n         <ul>\n            <li>\n               <p>For the <code>G.1X</code> worker type, each worker maps to 1 DPU (4 vCPUs, 16 GB of memory) with 94GB disk, and provides 1 executor per worker. We recommend this worker type for workloads such as data transforms, joins, and queries, to offers a scalable and cost effective way to run most jobs.</p>\n            </li>\n            <li>\n               <p>For the <code>G.2X</code> worker type, each worker maps to 2 DPU (8 vCPUs, 32 GB of memory) with 138GB disk, and provides 1 executor per worker. We recommend this worker type for workloads such as data transforms, joins, and queries, to offers a scalable and cost effective way to run most jobs.</p>\n            </li>\n            <li>\n               <p>For the <code>G.4X</code> worker type, each worker maps to 4 DPU (16 vCPUs, 64 GB of memory) with 256GB disk, and provides 1 executor per worker. We recommend this worker type for jobs whose workloads contain your most demanding transforms, aggregations, joins, and queries. This worker type is available only for Glue version 3.0 or later Spark ETL jobs in the following Amazon Web Services Regions: US East (Ohio), US East (N. Virginia), US West (N. California), US West (Oregon), Asia Pacific (Mumbai), Asia Pacific (Seoul), Asia Pacific (Singapore), Asia Pacific (Sydney), Asia Pacific (Tokyo), Canada (Central), Europe (Frankfurt), Europe (Ireland), Europe (London), Europe (Spain), Europe (Stockholm), and South America (São Paulo).</p>\n            </li>\n            <li>\n               <p>For the <code>G.8X</code> worker type, each worker maps to 8 DPU (32 vCPUs, 128 GB of memory) with 512GB disk, and provides 1 executor per worker. We recommend this worker type for jobs whose workloads contain your most demanding transforms, aggregations, joins, and queries. This worker type is available only for Glue version 3.0 or later Spark ETL jobs, in the same Amazon Web Services Regions as supported for the <code>G.4X</code> worker type.</p>\n            </li>\n            <li>\n               <p>For the <code>G.025X</code> worker type, each worker maps to 0.25 DPU (2 vCPUs, 4 GB of memory) with 84GB disk, and provides 1 executor per worker. We recommend this worker type for low volume streaming jobs. This worker type is only available for Glue version 3.0 or later streaming jobs.</p>\n            </li>\n            <li>\n               <p>For the <code>Z.2X</code> worker type, each worker maps to 2 M-DPU (8vCPUs, 64 GB of memory) with 128 GB disk, and provides up to 8 Ray workers based on the autoscaler.</p>\n            </li>\n         </ul>"}))
    CreateJobRequest.add_member(:code_gen_configuration_nodes, Smithy::Schema::Shapes::ShapeRef.new(shape: CodeGenConfigurationNodes, location_name: 'CodeGenConfigurationNodes', traits: {"smithy.api#documentation" => "<p>The representation of a directed acyclic graph on which both the Glue Studio visual component and Glue Studio code generation is based.</p>"}))
    CreateJobRequest.add_member(:execution_class, Smithy::Schema::Shapes::ShapeRef.new(shape: ExecutionClass, location_name: 'ExecutionClass', traits: {"smithy.api#documentation" => "<p>Indicates whether the job is run with a standard or flexible execution class. The standard execution-class is ideal for time-sensitive workloads that require fast job startup and dedicated resources.</p>\n         <p>The flexible execution class is appropriate for time-insensitive jobs whose start and completion times may vary. </p>\n         <p>Only jobs with Glue version 3.0 and above and command type <code>glueetl</code> will be allowed to set <code>ExecutionClass</code> to <code>FLEX</code>. The flexible execution class is available for Spark jobs.</p>"}))
    CreateJobRequest.add_member(:source_control_details, Smithy::Schema::Shapes::ShapeRef.new(shape: SourceControlDetails, location_name: 'SourceControlDetails', traits: {"smithy.api#documentation" => "<p>The details for a source control configuration for a job, allowing synchronization of job artifacts to or from a remote repository.</p>"}))
    CreateJobRequest.add_member(:maintenance_window, Smithy::Schema::Shapes::ShapeRef.new(shape: MaintenanceWindow, location_name: 'MaintenanceWindow', traits: {"smithy.api#documentation" => "<p>This field specifies a day of the week and hour for a maintenance window for streaming jobs. Glue periodically performs maintenance activities. During these maintenance windows, Glue will need to restart your streaming jobs.</p>\n         <p>Glue will restart the job within 3 hours of the specified maintenance window. For instance, if you set up the maintenance window for Monday at 10:00AM GMT, your jobs will be restarted between 10:00AM GMT to 1:00PM GMT.</p>"}))
    CreateJobRequest.type = Types::CreateJobRequest
    CreateJobResponse.add_member(:name, Smithy::Schema::Shapes::ShapeRef.new(shape: NameString, location_name: 'Name', traits: {"smithy.api#documentation" => "<p>The unique name that was provided for this job definition.</p>"}))
    CreateJobResponse.type = Types::CreateJobResponse
    CreateJsonClassifierRequest.add_member(:name, Smithy::Schema::Shapes::ShapeRef.new(shape: NameString, location_name: 'Name', traits: {"smithy.api#documentation" => "<p>The name of the classifier.</p>", "smithy.api#required" => {}}))
    CreateJsonClassifierRequest.add_member(:json_path, Smithy::Schema::Shapes::ShapeRef.new(shape: JsonPath, location_name: 'JsonPath', traits: {"smithy.api#documentation" => "<p>A <code>JsonPath</code> string defining the JSON data for the classifier to classify.\n      Glue supports a subset of JsonPath, as described in <a href=\"https://docs.aws.amazon.com/glue/latest/dg/custom-classifier.html#custom-classifier-json\">Writing JsonPath Custom Classifiers</a>.</p>", "smithy.api#required" => {}}))
    CreateJsonClassifierRequest.type = Types::CreateJsonClassifierRequest
    CreateMLTransformRequest.add_member(:name, Smithy::Schema::Shapes::ShapeRef.new(shape: NameString, location_name: 'Name', traits: {"smithy.api#documentation" => "<p>The unique name that you give the transform when you create it.</p>", "smithy.api#required" => {}}))
    CreateMLTransformRequest.add_member(:description, Smithy::Schema::Shapes::ShapeRef.new(shape: DescriptionString, location_name: 'Description', traits: {"smithy.api#documentation" => "<p>A description of the machine learning transform that is being defined. The default is an\n      empty string.</p>"}))
    CreateMLTransformRequest.add_member(:input_record_tables, Smithy::Schema::Shapes::ShapeRef.new(shape: GlueTables, location_name: 'InputRecordTables', traits: {"smithy.api#documentation" => "<p>A list of Glue table definitions used by the transform.</p>", "smithy.api#required" => {}}))
    CreateMLTransformRequest.add_member(:parameters, Smithy::Schema::Shapes::ShapeRef.new(shape: TransformParameters, location_name: 'Parameters', traits: {"smithy.api#documentation" => "<p>The algorithmic parameters that are specific to the transform type used. Conditionally\n      dependent on the transform type.</p>", "smithy.api#required" => {}}))
    CreateMLTransformRequest.add_member(:role, Smithy::Schema::Shapes::ShapeRef.new(shape: RoleString, location_name: 'Role', traits: {"smithy.api#documentation" => "<p>The name or Amazon Resource Name (ARN) of the IAM role with the required permissions. The required permissions include both Glue service role permissions to Glue resources, and Amazon S3 permissions required by the transform. </p>\n         <ul>\n            <li>\n               <p>This role needs Glue service role permissions to allow access to resources in Glue. See <a href=\"https://docs.aws.amazon.com/glue/latest/dg/attach-policy-iam-user.html\">Attach a Policy to IAM Users That Access Glue</a>.</p>\n            </li>\n            <li>\n               <p>This role needs permission to your Amazon Simple Storage Service (Amazon S3) sources, targets, temporary directory, scripts, and any libraries used by the task run for this transform.</p>\n            </li>\n         </ul>", "smithy.api#required" => {}}))
    CreateMLTransformRequest.add_member(:glue_version, Smithy::Schema::Shapes::ShapeRef.new(shape: GlueVersionString, location_name: 'GlueVersion', traits: {"smithy.api#documentation" => "<p>This value determines which version of Glue this machine learning transform is compatible with. Glue 1.0 is recommended for most customers. If the value is not set, the Glue compatibility defaults to Glue 0.9.  For more information, see <a href=\"https://docs.aws.amazon.com/glue/latest/dg/release-notes.html#release-notes-versions\">Glue Versions</a> in the developer guide.</p>"}))
    CreateMLTransformRequest.add_member(:max_capacity, Smithy::Schema::Shapes::ShapeRef.new(shape: NullableDouble, location_name: 'MaxCapacity', traits: {"smithy.api#documentation" => "<p>The number of Glue data processing units (DPUs) that are allocated to task runs for this transform. You can allocate from 2 to 100 DPUs; the default is 10. A DPU is a relative measure of\n      processing power that consists of 4 vCPUs of compute capacity and 16 GB of memory. For more\n      information, see the <a href=\"https://aws.amazon.com/glue/pricing/\">Glue pricing\n        page</a>. </p>\n         <p>\n            <code>MaxCapacity</code> is a mutually exclusive option with <code>NumberOfWorkers</code> and <code>WorkerType</code>.</p>\n         <ul>\n            <li>\n               <p>If either <code>NumberOfWorkers</code> or <code>WorkerType</code> is set, then <code>MaxCapacity</code> cannot be set.</p>\n            </li>\n            <li>\n               <p>If <code>MaxCapacity</code> is set then neither <code>NumberOfWorkers</code> or <code>WorkerType</code> can be set.</p>\n            </li>\n            <li>\n               <p>If <code>WorkerType</code> is set, then <code>NumberOfWorkers</code> is required (and vice versa).</p>\n            </li>\n            <li>\n               <p>\n                  <code>MaxCapacity</code> and <code>NumberOfWorkers</code> must both be at least 1.</p>\n            </li>\n         </ul>\n         <p>When the <code>WorkerType</code> field is set to a value other than <code>Standard</code>, the <code>MaxCapacity</code> field is set automatically and becomes read-only.</p>\n         <p>When the <code>WorkerType</code> field is set to a value other than <code>Standard</code>, the <code>MaxCapacity</code> field is set automatically and becomes read-only.</p>"}))
    CreateMLTransformRequest.add_member(:worker_type, Smithy::Schema::Shapes::ShapeRef.new(shape: WorkerType, location_name: 'WorkerType', traits: {"smithy.api#documentation" => "<p>The type of predefined worker that is allocated when this task runs. Accepts a value of Standard, G.1X, or G.2X.</p>\n         <ul>\n            <li>\n               <p>For the <code>Standard</code> worker type, each worker provides 4 vCPU, 16 GB of memory and a 50GB disk, and 2 executors per worker.</p>\n            </li>\n            <li>\n               <p>For the <code>G.1X</code> worker type, each worker provides 4 vCPU, 16 GB of memory and a 64GB disk, and 1 executor per worker.</p>\n            </li>\n            <li>\n               <p>For the <code>G.2X</code> worker type, each worker provides 8 vCPU, 32 GB of memory and a 128GB disk, and 1 executor per worker.</p>\n            </li>\n         </ul>\n         <p>\n            <code>MaxCapacity</code> is a mutually exclusive option with <code>NumberOfWorkers</code> and <code>WorkerType</code>.</p>\n         <ul>\n            <li>\n               <p>If either <code>NumberOfWorkers</code> or <code>WorkerType</code> is set, then <code>MaxCapacity</code> cannot be set.</p>\n            </li>\n            <li>\n               <p>If <code>MaxCapacity</code> is set then neither <code>NumberOfWorkers</code> or <code>WorkerType</code> can be set.</p>\n            </li>\n            <li>\n               <p>If <code>WorkerType</code> is set, then <code>NumberOfWorkers</code> is required (and vice versa).</p>\n            </li>\n            <li>\n               <p>\n                  <code>MaxCapacity</code> and <code>NumberOfWorkers</code> must both be at least 1.</p>\n            </li>\n         </ul>"}))
    CreateMLTransformRequest.add_member(:number_of_workers, Smithy::Schema::Shapes::ShapeRef.new(shape: NullableInteger, location_name: 'NumberOfWorkers', traits: {"smithy.api#documentation" => "<p>The number of workers of a defined <code>workerType</code> that are allocated when this task runs.</p>\n         <p>If <code>WorkerType</code> is set, then <code>NumberOfWorkers</code> is required (and vice versa).</p>"}))
    CreateMLTransformRequest.add_member(:timeout, Smithy::Schema::Shapes::ShapeRef.new(shape: Timeout, location_name: 'Timeout', traits: {"smithy.api#documentation" => "<p>The timeout of the task run for this transform in minutes. This is the maximum time that a task run for this transform can consume resources before it is terminated and enters <code>TIMEOUT</code> status. The default is 2,880 minutes (48 hours).</p>"}))
    CreateMLTransformRequest.add_member(:max_retries, Smithy::Schema::Shapes::ShapeRef.new(shape: NullableInteger, location_name: 'MaxRetries', traits: {"smithy.api#documentation" => "<p>The maximum number of times to retry a task for this transform after a task run fails.</p>"}))
    CreateMLTransformRequest.add_member(:tags, Smithy::Schema::Shapes::ShapeRef.new(shape: TagsMap, location_name: 'Tags', traits: {"smithy.api#documentation" => "<p>The tags to use with this machine learning transform. You may use tags to limit access to the machine learning transform. For more information about tags in Glue, see <a href=\"https://docs.aws.amazon.com/glue/latest/dg/monitor-tags.html\">Amazon Web Services Tags in Glue</a> in the developer guide.</p>"}))
    CreateMLTransformRequest.add_member(:transform_encryption, Smithy::Schema::Shapes::ShapeRef.new(shape: TransformEncryption, location_name: 'TransformEncryption', traits: {"smithy.api#documentation" => "<p>The encryption-at-rest settings of the transform that apply to accessing user data. Machine learning transforms can access user data encrypted in Amazon S3 using KMS.</p>"}))
    CreateMLTransformRequest.type = Types::CreateMLTransformRequest
    CreateMLTransformResponse.add_member(:transform_id, Smithy::Schema::Shapes::ShapeRef.new(shape: HashString, location_name: 'TransformId', traits: {"smithy.api#documentation" => "<p>A unique identifier that is generated for the transform.</p>"}))
    CreateMLTransformResponse.type = Types::CreateMLTransformResponse
    CreatePartitionIndexRequest.add_member(:catalog_id, Smithy::Schema::Shapes::ShapeRef.new(shape: CatalogIdString, location_name: 'CatalogId', traits: {"smithy.api#documentation" => "<p>The catalog ID where the table resides.</p>"}))
    CreatePartitionIndexRequest.add_member(:database_name, Smithy::Schema::Shapes::ShapeRef.new(shape: NameString, location_name: 'DatabaseName', traits: {"smithy.api#documentation" => "<p>Specifies the name of a database in which you want to create a partition index.</p>", "smithy.api#required" => {}}))
    CreatePartitionIndexRequest.add_member(:table_name, Smithy::Schema::Shapes::ShapeRef.new(shape: NameString, location_name: 'TableName', traits: {"smithy.api#documentation" => "<p>Specifies the name of a table in which you want to create a partition index.</p>", "smithy.api#required" => {}}))
    CreatePartitionIndexRequest.add_member(:partition_index, Smithy::Schema::Shapes::ShapeRef.new(shape: PartitionIndex, location_name: 'PartitionIndex', traits: {"smithy.api#documentation" => "<p>Specifies a <code>PartitionIndex</code> structure to create a partition index in an existing table.</p>", "smithy.api#required" => {}}))
    CreatePartitionIndexRequest.type = Types::CreatePartitionIndexRequest
    CreatePartitionIndexResponse.type = Types::CreatePartitionIndexResponse
