    CreatePartitionRequest.add_member(:database_name, Smithy::Schema::Shapes::ShapeRef.new(shape: NameString, location_name: 'DatabaseName', traits: {"smithy.api#documentation" => "<p>The name of the metadata database in which the partition is\n      to be created.</p>", "smithy.api#required" => {}}))
