    DevEndpoint.add_member(:public_address, Smithy::Schema::Shapes::ShapeRef.new(shape: GenericString, location_name: 'PublicAddress', traits: {"smithy.api#documentation" => "<p>The public IP address used by this <code>DevEndpoint</code>. The\n        <code>PublicAddress</code> field is present only when you create a non-virtual private cloud\n      (VPC) <code>DevEndpoint</code>.</p>"}))
