    GetMLTransformResponse.add_member(:max_capacity, Smithy::Schema::Shapes::ShapeRef.new(shape: NullableDouble, location_name: 'MaxCapacity', traits: {"smithy.api#documentation" => "<p>The number of Glue data processing units (DPUs) that are allocated to task runs for this transform. You can allocate from 2 to 100 DPUs; the default is 10. A DPU is a relative measure of\n      processing power that consists of 4 vCPUs of compute capacity and 16 GB of memory. For more\n      information, see the <a href=\"https://aws.amazon.com/glue/pricing/\">Glue pricing\n        page</a>. </p>\n         <p>When the <code>WorkerType</code> field is set to a value other than <code>Standard</code>, the <code>MaxCapacity</code> field is set automatically and becomes read-only.</p>"}))
    GetMLTransformResponse.add_member(:worker_type, Smithy::Schema::Shapes::ShapeRef.new(shape: WorkerType, location_name: 'WorkerType', traits: {"smithy.api#documentation" => "<p>The type of predefined worker that is allocated when this task runs. Accepts a value of Standard, G.1X, or G.2X.</p>\n         <ul>\n            <li>\n               <p>For the <code>Standard</code> worker type, each worker provides 4 vCPU, 16 GB of memory and a 50GB disk, and 2 executors per worker.</p>\n            </li>\n            <li>\n               <p>For the <code>G.1X</code> worker type, each worker provides 4 vCPU, 16 GB of memory and a 64GB disk, and 1 executor per worker.</p>\n            </li>\n            <li>\n               <p>For the <code>G.2X</code> worker type, each worker provides 8 vCPU, 32 GB of memory and a 128GB disk, and 1 executor per worker.</p>\n            </li>\n         </ul>"}))
