    GetPartitionsRequest.add_member(:transaction_id, Smithy::Schema::Shapes::ShapeRef.new(shape: TransactionIdString, location_name: 'TransactionId', traits: {"smithy.api#documentation" => "<p>The transaction ID at which to read the partition contents.</p>"}))
