    GetUnfilteredPartitionsMetadataRequest.add_member(:database_name, Smithy::Schema::Shapes::ShapeRef.new(shape: NameString, location_name: 'DatabaseName', traits: {"smithy.api#documentation" => "<p>The name of the catalog database where the partitions reside.</p>", "smithy.api#required" => {}}))
