    GetUnfilteredPartitionsMetadataRequest.add_member(:supported_permission_types, Smithy::Schema::Shapes::ShapeRef.new(shape: PermissionTypeList, location_name: 'SupportedPermissionTypes', traits: {"smithy.api#documentation" => "<p>A list of supported permission types. </p>", "smithy.api#required" => {}}))
