    Integration.add_member(:kms_key_id, Smithy::Schema::Shapes::ShapeRef.new(shape: String2048, location_name: 'KmsKeyId', traits: {"smithy.api#documentation" => "<p>The ARN of a KMS key used for encrypting the channel.</p>"}))
    Integration.add_member(:additional_encryption_context, Smithy::Schema::Shapes::ShapeRef.new(shape: IntegrationAdditionalEncryptionContextMap, location_name: 'AdditionalEncryptionContext', traits: {"smithy.api#documentation" => "<p>An optional set of non-secret key–value pairs that contains additional contextual information for encryption. This can only be provided if <code>KMSKeyId</code> is provided.</p>"}))
    Integration.add_member(:tags, Smithy::Schema::Shapes::ShapeRef.new(shape: IntegrationTagsList, location_name: 'Tags', traits: {"smithy.api#documentation" => "<p>Metadata assigned to the resource consisting of a list of key-value pairs.</p>"}))
    Integration.add_member(:status, Smithy::Schema::Shapes::ShapeRef.new(shape: IntegrationStatus, location_name: 'Status', traits: {"smithy.api#documentation" => "<p>The possible statuses are:</p>\n         <ul>\n            <li>\n               <p>CREATING: The integration is being created.</p>\n            </li>\n            <li>\n               <p>ACTIVE: The integration creation succeeds.</p>\n            </li>\n            <li>\n               <p>MODIFYING: The integration is being modified.</p>\n            </li>\n            <li>\n               <p>FAILED: The integration creation fails. </p>\n            </li>\n            <li>\n               <p>DELETING: The integration is deleted.</p>\n            </li>\n            <li>\n               <p>SYNCING: The integration is synchronizing.</p>\n            </li>\n            <li>\n               <p>NEEDS_ATTENTION: The integration needs attention, such as synchronization.</p>\n            </li>\n         </ul>", "smithy.api#required" => {}}))
