    JDBCConnectorOptions.add_member(:partition_column, Smithy::Schema::Shapes::ShapeRef.new(shape: EnclosedInStringProperty, location_name: 'PartitionColumn', traits: {"smithy.api#documentation" => "<p>The name of an integer column that is used for partitioning. This option works only when it's included with <code>lowerBound</code>, <code>upperBound</code>, and <code>numPartitions</code>. This option works the same way as in the Spark SQL JDBC reader.</p>"}))
    JDBCConnectorOptions.add_member(:lower_bound, Smithy::Schema::Shapes::ShapeRef.new(shape: BoxedNonNegativeLong, location_name: 'LowerBound', traits: {"smithy.api#documentation" => "<p>The minimum value of <code>partitionColumn</code> that is used to decide partition stride.</p>"}))
    JDBCConnectorOptions.add_member(:upper_bound, Smithy::Schema::Shapes::ShapeRef.new(shape: BoxedNonNegativeLong, location_name: 'UpperBound', traits: {"smithy.api#documentation" => "<p>The maximum value of <code>partitionColumn</code> that is used to decide partition stride.</p>"}))
    JDBCConnectorOptions.add_member(:num_partitions, Smithy::Schema::Shapes::ShapeRef.new(shape: BoxedNonNegativeLong, location_name: 'NumPartitions', traits: {"smithy.api#documentation" => "<p>The number of partitions. This value, along with <code>lowerBound</code> (inclusive) and <code>upperBound</code> (exclusive), form partition strides for generated <code>WHERE</code> clause expressions that are used to split the <code>partitionColumn</code>.</p>"}))
    JDBCConnectorOptions.add_member(:job_bookmark_keys, Smithy::Schema::Shapes::ShapeRef.new(shape: EnclosedInStringProperties, location_name: 'JobBookmarkKeys', traits: {"smithy.api#documentation" => "<p>The name of the job bookmark keys on which to sort.</p>"}))
    JDBCConnectorOptions.add_member(:job_bookmark_keys_sort_order, Smithy::Schema::Shapes::ShapeRef.new(shape: EnclosedInStringProperty, location_name: 'JobBookmarkKeysSortOrder', traits: {"smithy.api#documentation" => "<p>Specifies an ascending or descending sort order.</p>"}))
    JDBCConnectorOptions.add_member(:data_type_mapping, Smithy::Schema::Shapes::ShapeRef.new(shape: JDBCDataTypeMapping, location_name: 'DataTypeMapping', traits: {"smithy.api#documentation" => "<p>Custom data type mapping that builds a mapping from a JDBC data type to an Glue data type. For example, the option <code>\"dataTypeMapping\":{\"FLOAT\":\"STRING\"}</code> maps data fields of JDBC type <code>FLOAT</code> into the Java <code>String</code> type by calling the <code>ResultSet.getString()</code> method of the driver, and uses it to build the Glue record. The <code>ResultSet</code> object is implemented by each driver, so the behavior is specific to the driver you use. Refer to the documentation for your JDBC driver to understand how the driver performs the conversions.</p>"}))
