    JdbcTarget.add_member(:enable_additional_metadata, Smithy::Schema::Shapes::ShapeRef.new(shape: EnableAdditionalMetadata, location_name: 'EnableAdditionalMetadata', traits: {"smithy.api#documentation" => "<p>Specify a value of <code>RAWTYPES</code> or <code>COMMENTS</code> to enable additional metadata in table responses. <code>RAWTYPES</code> provides the native-level datatype. <code>COMMENTS</code> provides comments associated with a column or table in the database.</p>\n         <p>If you do not need additional metadata, keep the field empty.</p>"}))
