    Job.add_member(:name, Smithy::Schema::Shapes::ShapeRef.new(shape: NameString, location_name: 'Name', traits: {"smithy.api#documentation" => "<p>The name you assign to this job definition.</p>"}))
    Job.add_member(:job_mode, Smithy::Schema::Shapes::ShapeRef.new(shape: JobMode, location_name: 'JobMode', traits: {"smithy.api#documentation" => "<p>A mode that describes how a job was created. Valid values are:</p>\n         <ul>\n            <li>\n               <p>\n                  <code>SCRIPT</code> - The job was created using the Glue Studio script editor.</p>\n            </li>\n            <li>\n               <p>\n                  <code>VISUAL</code> - The job was created using the Glue Studio visual editor.</p>\n            </li>\n            <li>\n               <p>\n                  <code>NOTEBOOK</code> - The job was created using an interactive sessions notebook.</p>\n            </li>\n         </ul>\n         <p>When the <code>JobMode</code> field is missing or null, <code>SCRIPT</code> is assigned as the default value.</p>"}))
    Job.add_member(:job_run_queuing_enabled, Smithy::Schema::Shapes::ShapeRef.new(shape: NullableBoolean, location_name: 'JobRunQueuingEnabled', traits: {"smithy.api#documentation" => "<p>Specifies whether job run queuing is enabled for the job runs for this job.</p>\n         <p>A value of true means job run queuing is enabled for the job runs. If false or not populated, the job runs will not be considered for queueing.</p>\n         <p>If this field does not match the value set in the job run, then the value from the job run field will be used.</p>"}))
    Job.add_member(:description, Smithy::Schema::Shapes::ShapeRef.new(shape: DescriptionString, location_name: 'Description', traits: {"smithy.api#documentation" => "<p>A description of the job.</p>"}))
    Job.add_member(:log_uri, Smithy::Schema::Shapes::ShapeRef.new(shape: UriString, location_name: 'LogUri', traits: {"smithy.api#documentation" => "<p>This field is reserved for future use.</p>"}))
    Job.add_member(:role, Smithy::Schema::Shapes::ShapeRef.new(shape: RoleString, location_name: 'Role', traits: {"smithy.api#documentation" => "<p>The name or Amazon Resource Name (ARN) of the IAM role associated with this job.</p>"}))
    Job.add_member(:created_on, Smithy::Schema::Shapes::ShapeRef.new(shape: TimestampValue, location_name: 'CreatedOn', traits: {"smithy.api#documentation" => "<p>The time and date that this job definition was created.</p>"}))
    Job.add_member(:last_modified_on, Smithy::Schema::Shapes::ShapeRef.new(shape: TimestampValue, location_name: 'LastModifiedOn', traits: {"smithy.api#documentation" => "<p>The last point in time when this job definition was modified.</p>"}))
    Job.add_member(:execution_property, Smithy::Schema::Shapes::ShapeRef.new(shape: ExecutionProperty, location_name: 'ExecutionProperty', traits: {"smithy.api#documentation" => "<p>An <code>ExecutionProperty</code> specifying the maximum number of concurrent runs allowed\n      for this job.</p>"}))
    Job.add_member(:command, Smithy::Schema::Shapes::ShapeRef.new(shape: JobCommand, location_name: 'Command', traits: {"smithy.api#documentation" => "<p>The <code>JobCommand</code> that runs this job.</p>"}))
    Job.add_member(:default_arguments, Smithy::Schema::Shapes::ShapeRef.new(shape: GenericMap, location_name: 'DefaultArguments', traits: {"smithy.api#documentation" => "<p>The default arguments for every run of this job, specified as name-value pairs.</p>\n         <p>You can specify arguments here that your own job-execution script\n      consumes, as well as arguments that Glue itself consumes.</p>\n         <p>Job arguments may be logged. Do not pass plaintext secrets as arguments. Retrieve secrets\n      from a Glue Connection, Secrets Manager or other secret management\n      mechanism if you intend to keep them within the Job. </p>\n         <p>For information about how to specify and consume your own Job arguments, see the <a href=\"https://docs.aws.amazon.com/glue/latest/dg/aws-glue-programming-python-calling.html\">Calling Glue APIs in Python</a> topic in the developer guide.</p>\n         <p>For information about the arguments you can provide to this field when configuring Spark jobs,\n     see the <a href=\"https://docs.aws.amazon.com/glue/latest/dg/aws-glue-programming-etl-glue-arguments.html\">Special Parameters Used by Glue</a> topic in the developer guide.</p>\n         <p>For information about the arguments you can provide to this field when configuring Ray\n      jobs, see <a href=\"https://docs.aws.amazon.com/glue/latest/dg/author-job-ray-job-parameters.html\">Using\n      job parameters in Ray jobs</a> in the developer guide.</p>"}))
    Job.add_member(:non_overridable_arguments, Smithy::Schema::Shapes::ShapeRef.new(shape: GenericMap, location_name: 'NonOverridableArguments', traits: {"smithy.api#documentation" => "<p>Arguments for this job that are not overridden when providing job arguments\n      in a job run, specified as name-value pairs.</p>"}))
    Job.add_member(:connections, Smithy::Schema::Shapes::ShapeRef.new(shape: ConnectionsList, location_name: 'Connections', traits: {"smithy.api#documentation" => "<p>The connections used for this job.</p>"}))
    Job.add_member(:max_retries, Smithy::Schema::Shapes::ShapeRef.new(shape: MaxRetries, location_name: 'MaxRetries', traits: {"smithy.api#default" => 0, "smithy.api#documentation" => "<p>The maximum number of times to retry this job after a JobRun fails.</p>"}))
    Job.add_member(:allocated_capacity, Smithy::Schema::Shapes::ShapeRef.new(shape: IntegerValue, location_name: 'AllocatedCapacity', traits: {"smithy.api#default" => 0, "smithy.api#deprecated" => {"message" => "This property is deprecated, use MaxCapacity instead."}, "smithy.api#documentation" => "<p>This field is deprecated. Use <code>MaxCapacity</code> instead.</p>\n         <p>The number of Glue data processing units (DPUs) allocated to runs of this job. You can\n      allocate a minimum of 2 DPUs; the default is 10. A DPU is a relative measure of processing\n      power that consists of 4 vCPUs of compute capacity and 16 GB of memory. For more information,\n      see the <a href=\"https://aws.amazon.com/glue/pricing/\">Glue pricing\n      page</a>.</p>\n         <p></p>"}))
    Job.add_member(:timeout, Smithy::Schema::Shapes::ShapeRef.new(shape: Timeout, location_name: 'Timeout', traits: {"smithy.api#documentation" => "<p>The job timeout in minutes.  This is the maximum time that a job run\n      can consume resources before it is terminated and enters <code>TIMEOUT</code>\n      status.</p>\n         <p>Jobs must have timeout values less than 7 days or 10080 minutes. Otherwise, the jobs will throw an exception.</p>\n         <p>When the value is left blank, the timeout is defaulted to 2880 minutes.</p>\n         <p>Any existing Glue jobs that had a timeout value greater than 7 days will be defaulted to 7 days. For instance if you have specified a timeout of 20 days for a batch job, it will be stopped on the 7th day.</p>\n         <p>For streaming jobs, if you have set up a maintenance window, it will be restarted during the maintenance window after 7 days.</p>"}))
    Job.add_member(:max_capacity, Smithy::Schema::Shapes::ShapeRef.new(shape: NullableDouble, location_name: 'MaxCapacity', traits: {"smithy.api#documentation" => "<p>For Glue version 1.0 or earlier jobs, using the standard worker type, the number of\n      Glue data processing units (DPUs) that can be allocated when this job runs. A DPU is\n      a relative measure of processing power that consists of 4 vCPUs of compute capacity and 16 GB\n      of memory. For more information, see the <a href=\"https://aws.amazon.com/glue/pricing/\">\n        Glue pricing page</a>.</p>\n         <p>For Glue version 2.0 or later jobs, you cannot specify a <code>Maximum capacity</code>.\n      Instead, you should specify a <code>Worker type</code> and the <code>Number of workers</code>.</p>\n         <p>Do not set <code>MaxCapacity</code> if using <code>WorkerType</code> and <code>NumberOfWorkers</code>.</p>\n         <p>The value that can be allocated for <code>MaxCapacity</code> depends on whether you are\n      running a Python shell job, an Apache Spark ETL job, or an Apache Spark streaming ETL\n      job:</p>\n         <ul>\n            <li>\n               <p>When you specify a Python shell job (<code>JobCommand.Name</code>=\"pythonshell\"), you can\n          allocate either 0.0625 or 1 DPU. The default is 0.0625 DPU.</p>\n            </li>\n            <li>\n               <p>When you specify an Apache Spark ETL job (<code>JobCommand.Name</code>=\"glueetl\") or Apache \n            Spark streaming ETL job (<code>JobCommand.Name</code>=\"gluestreaming\"), you can allocate from 2 to 100 DPUs. \n            The default is 10 DPUs. This job type cannot have a fractional DPU allocation.</p>\n            </li>\n         </ul>"}))
    Job.add_member(:worker_type, Smithy::Schema::Shapes::ShapeRef.new(shape: WorkerType, location_name: 'WorkerType', traits: {"smithy.api#documentation" => "<p>The type of predefined worker that is allocated when a job runs.</p>\n         <p>Glue provides multiple worker types to accommodate different workload requirements:</p>\n         <p>G Worker Types (General-purpose compute workers):</p>\n         <ul>\n            <li>\n               <p>G.1X: 1 DPU (4 vCPUs, 16 GB memory, 94GB disk)</p>\n            </li>\n            <li>\n               <p>G.2X: 2 DPU (8 vCPUs, 32 GB memory, 138GB disk)</p>\n            </li>\n            <li>\n               <p>G.4X: 4 DPU (16 vCPUs, 64 GB memory, 256GB disk)</p>\n            </li>\n            <li>\n               <p>G.8X: 8 DPU (32 vCPUs, 128 GB memory, 512GB disk)</p>\n            </li>\n            <li>\n               <p>G.12X: 12 DPU (48 vCPUs, 192 GB memory, 768GB disk)</p>\n            </li>\n            <li>\n               <p>G.16X: 16 DPU (64 vCPUs, 256 GB memory, 1024GB disk)</p>\n            </li>\n         </ul>\n         <p>R Worker Types (Memory-optimized workers):</p>\n         <ul>\n            <li>\n               <p>R.1X: 1 M-DPU (4 vCPUs, 32 GB memory)</p>\n            </li>\n            <li>\n               <p>R.2X: 2 M-DPU (8 vCPUs, 64 GB memory)</p>\n            </li>\n            <li>\n               <p>R.4X: 4 M-DPU (16 vCPUs, 128 GB memory)</p>\n            </li>\n            <li>\n               <p>R.8X: 8 M-DPU (32 vCPUs, 256 GB memory)</p>\n            </li>\n         </ul>"}))
    Job.add_member(:number_of_workers, Smithy::Schema::Shapes::ShapeRef.new(shape: NullableInteger, location_name: 'NumberOfWorkers', traits: {"smithy.api#documentation" => "<p>The number of workers of a defined <code>workerType</code> that are allocated when a job runs.</p>"}))
    Job.add_member(:security_configuration, Smithy::Schema::Shapes::ShapeRef.new(shape: NameString, location_name: 'SecurityConfiguration', traits: {"smithy.api#documentation" => "<p>The name of the <code>SecurityConfiguration</code> structure to be used with this\n      job.</p>"}))
    Job.add_member(:notification_property, Smithy::Schema::Shapes::ShapeRef.new(shape: NotificationProperty, location_name: 'NotificationProperty', traits: {"smithy.api#documentation" => "<p>Specifies configuration properties of a job notification.</p>"}))
    Job.add_member(:glue_version, Smithy::Schema::Shapes::ShapeRef.new(shape: GlueVersionString, location_name: 'GlueVersion', traits: {"smithy.api#documentation" => "<p>In Spark jobs, <code>GlueVersion</code> determines the versions of Apache Spark and Python\n      that Glue available in a job. The Python version indicates the version\n      supported for jobs of type Spark. </p>\n         <p>Ray jobs should set <code>GlueVersion</code> to <code>4.0</code> or greater. However,\n    the versions of Ray, Python and additional libraries available in your Ray job are determined\n    by the <code>Runtime</code> parameter of the Job command.</p>\n         <p>For more information about the available Glue versions and corresponding\n      Spark and Python versions, see <a href=\"https://docs.aws.amazon.com/glue/latest/dg/add-job.html\">Glue version</a> in the developer\n      guide.</p>\n         <p>Jobs that are created without specifying a Glue version default to Glue 0.9.</p>"}))
    Job.add_member(:code_gen_configuration_nodes, Smithy::Schema::Shapes::ShapeRef.new(shape: CodeGenConfigurationNodes, location_name: 'CodeGenConfigurationNodes', traits: {"smithy.api#documentation" => "<p>The representation of a directed acyclic graph on which both the Glue Studio visual component and Glue Studio code generation is based.</p>"}))
    Job.add_member(:execution_class, Smithy::Schema::Shapes::ShapeRef.new(shape: ExecutionClass, location_name: 'ExecutionClass', traits: {"smithy.api#documentation" => "<p>Indicates whether the job is run with a standard or flexible execution class. The standard execution class is ideal for time-sensitive workloads that require fast job startup and dedicated resources.</p>\n         <p>The flexible execution class is appropriate for time-insensitive jobs whose start and completion times may vary. </p>\n         <p>Only jobs with Glue version 3.0 and above and command type <code>glueetl</code> will be allowed to set <code>ExecutionClass</code> to <code>FLEX</code>. The flexible execution class is available for Spark jobs.</p>"}))
    Job.add_member(:source_control_details, Smithy::Schema::Shapes::ShapeRef.new(shape: SourceControlDetails, location_name: 'SourceControlDetails', traits: {"smithy.api#documentation" => "<p>The details for a source control configuration for a job, allowing synchronization of job artifacts to or from a remote repository.</p>"}))
    Job.add_member(:maintenance_window, Smithy::Schema::Shapes::ShapeRef.new(shape: MaintenanceWindow, location_name: 'MaintenanceWindow', traits: {"smithy.api#documentation" => "<p>This field specifies a day of the week and hour for a maintenance window for streaming jobs. Glue periodically performs maintenance activities. During these maintenance windows, Glue will need to restart your streaming jobs.</p>\n         <p>Glue will restart the job within 3 hours of the specified maintenance window. For instance, if you set up the maintenance window for Monday at 10:00AM GMT, your jobs will be restarted between 10:00AM GMT to 1:00PM GMT.</p>"}))
    Job.add_member(:profile_name, Smithy::Schema::Shapes::ShapeRef.new(shape: NameString, location_name: 'ProfileName', traits: {"smithy.api#documentation" => "<p>The name of an Glue usage profile associated with the job.</p>"}))
    Job.type = Types::Job
