    JobBookmarkEntry.add_member(:run, Smithy::Schema::Shapes::ShapeRef.new(shape: IntegerValue, location_name: 'Run', traits: {"smithy.api#default" => 0, "smithy.api#documentation" => "<p>The run ID number.</p>"}))
    JobBookmarkEntry.add_member(:attempt, Smithy::Schema::Shapes::ShapeRef.new(shape: IntegerValue, location_name: 'Attempt', traits: {"smithy.api#default" => 0, "smithy.api#documentation" => "<p>The attempt ID number.</p>"}))
    JobBookmarkEntry.add_member(:previous_run_id, Smithy::Schema::Shapes::ShapeRef.new(shape: RunId, location_name: 'PreviousRunId', traits: {"smithy.api#documentation" => "<p>The unique run identifier associated with the previous job run.</p>"}))
