    JobBookmarksEncryption.add_member(:job_bookmarks_encryption_mode, Smithy::Schema::Shapes::ShapeRef.new(shape: JobBookmarksEncryptionMode, location_name: 'JobBookmarksEncryptionMode', traits: {"smithy.api#documentation" => "<p>The encryption mode to use for job bookmarks data.</p>"}))
    JobBookmarksEncryption.add_member(:kms_key_arn, Smithy::Schema::Shapes::ShapeRef.new(shape: KmsKeyArn, location_name: 'KmsKeyArn', traits: {"smithy.api#documentation" => "<p>The Amazon Resource Name (ARN) of the KMS key to be used to encrypt the data.</p>"}))
