    JobCommand.add_member(:name, Smithy::Schema::Shapes::ShapeRef.new(shape: GenericString, location_name: 'Name', traits: {"smithy.api#documentation" => "<p>The name of the job command. For an Apache Spark ETL job, this must be\n      <code>glueetl</code>. For a Python shell job, it must be <code>pythonshell</code>. \n      For an Apache Spark streaming ETL job, this must be <code>gluestreaming</code>. For a Ray job,\n      this must be <code>glueray</code>.</p>"}))
    JobCommand.add_member(:script_location, Smithy::Schema::Shapes::ShapeRef.new(shape: ScriptLocationString, location_name: 'ScriptLocation', traits: {"smithy.api#documentation" => "<p>Specifies the Amazon Simple Storage Service (Amazon S3) path to a script that runs a\n      job.</p>"}))
    JobCommand.add_member(:python_version, Smithy::Schema::Shapes::ShapeRef.new(shape: PythonVersionString, location_name: 'PythonVersion', traits: {"smithy.api#documentation" => "<p>The Python version being used to run a Python shell job. Allowed values are 2 or 3.</p>"}))
    JobCommand.add_member(:runtime, Smithy::Schema::Shapes::ShapeRef.new(shape: RuntimeNameString, location_name: 'Runtime', traits: {"smithy.api#documentation" => "<p>In Ray jobs, Runtime is used to specify the versions of Ray, Python and additional\n      libraries available in your environment. This field is not used in other job types. For\n      supported runtime environment values, see <a href=\"https://docs.aws.amazon.com/glue/latest/dg/ray-jobs-section.html\">Supported Ray runtime environments</a>\n      in the Glue Developer Guide.</p>"}))
