    JobRun.add_member(:previous_run_id, Smithy::Schema::Shapes::ShapeRef.new(shape: IdString, location_name: 'PreviousRunId', traits: {"smithy.api#documentation" => "<p>The ID of the previous run of this job. For example, the <code>JobRunId</code> specified\n      in the <code>StartJobRun</code> action.</p>"}))
    JobRun.add_member(:trigger_name, Smithy::Schema::Shapes::ShapeRef.new(shape: NameString, location_name: 'TriggerName', traits: {"smithy.api#documentation" => "<p>The name of the trigger that started this job run.</p>"}))
    JobRun.add_member(:job_name, Smithy::Schema::Shapes::ShapeRef.new(shape: NameString, location_name: 'JobName', traits: {"smithy.api#documentation" => "<p>The name of the job definition being used in this run.</p>"}))
    JobRun.add_member(:job_mode, Smithy::Schema::Shapes::ShapeRef.new(shape: JobMode, location_name: 'JobMode', traits: {"smithy.api#documentation" => "<p>A mode that describes how a job was created. Valid values are:</p>\n         <ul>\n            <li>\n               <p>\n                  <code>SCRIPT</code> - The job was created using the Glue Studio script editor.</p>\n            </li>\n            <li>\n               <p>\n                  <code>VISUAL</code> - The job was created using the Glue Studio visual editor.</p>\n            </li>\n            <li>\n               <p>\n                  <code>NOTEBOOK</code> - The job was created using an interactive sessions notebook.</p>\n            </li>\n         </ul>\n         <p>When the <code>JobMode</code> field is missing or null, <code>SCRIPT</code> is assigned as the default value.</p>"}))
    JobRun.add_member(:job_run_queuing_enabled, Smithy::Schema::Shapes::ShapeRef.new(shape: NullableBoolean, location_name: 'JobRunQueuingEnabled', traits: {"smithy.api#documentation" => "<p>Specifies whether job run queuing is enabled for the job run.</p>\n         <p>A value of true means job run queuing is enabled for the job run. If false or not populated, the job run will not be considered for queueing.</p>"}))
    JobRun.add_member(:started_on, Smithy::Schema::Shapes::ShapeRef.new(shape: TimestampValue, location_name: 'StartedOn', traits: {"smithy.api#documentation" => "<p>The date and time at which this job run was started.</p>"}))
    JobRun.add_member(:last_modified_on, Smithy::Schema::Shapes::ShapeRef.new(shape: TimestampValue, location_name: 'LastModifiedOn', traits: {"smithy.api#documentation" => "<p>The last time that this job run was modified.</p>"}))
    JobRun.add_member(:completed_on, Smithy::Schema::Shapes::ShapeRef.new(shape: TimestampValue, location_name: 'CompletedOn', traits: {"smithy.api#documentation" => "<p>The date and time that this job run completed.</p>"}))
    JobRun.add_member(:job_run_state, Smithy::Schema::Shapes::ShapeRef.new(shape: JobRunState, location_name: 'JobRunState', traits: {"smithy.api#documentation" => "<p>The current state of the job run. For more information about the statuses of jobs that have terminated abnormally, see <a href=\"https://docs.aws.amazon.com/glue/latest/dg/job-run-statuses.html\">Glue Job Run Statuses</a>.</p>"}))
    JobRun.add_member(:arguments, Smithy::Schema::Shapes::ShapeRef.new(shape: GenericMap, location_name: 'Arguments', traits: {"smithy.api#documentation" => "<p>The job arguments associated with this run. For this job run, they replace the default\n      arguments set in the job definition itself.</p>\n         <p>You can specify arguments here that your own job-execution script\n      consumes, as well as arguments that Glue itself consumes.</p>\n         <p>Job arguments may be logged. Do not pass plaintext secrets as arguments. Retrieve secrets\n      from a Glue Connection, Secrets Manager or other secret management\n      mechanism if you intend to keep them within the Job. </p>\n         <p>For information about how to specify and consume your own Job arguments, see the <a href=\"https://docs.aws.amazon.com/glue/latest/dg/aws-glue-programming-python-calling.html\">Calling Glue APIs in Python</a> topic in the developer guide.</p>\n         <p>For information about the arguments you can provide to this field when configuring Spark jobs,\n     see the <a href=\"https://docs.aws.amazon.com/glue/latest/dg/aws-glue-programming-etl-glue-arguments.html\">Special Parameters Used by Glue</a> topic in the developer guide.</p>\n         <p>For information about the arguments you can provide to this field when configuring Ray\n      jobs, see <a href=\"https://docs.aws.amazon.com/glue/latest/dg/author-job-ray-job-parameters.html\">Using\n      job parameters in Ray jobs</a> in the developer guide.</p>"}))
    JobRun.add_member(:error_message, Smithy::Schema::Shapes::ShapeRef.new(shape: ErrorString, location_name: 'ErrorMessage', traits: {"smithy.api#documentation" => "<p>An error message associated with this job run.</p>"}))
    JobRun.add_member(:predecessor_runs, Smithy::Schema::Shapes::ShapeRef.new(shape: PredecessorList, location_name: 'PredecessorRuns', traits: {"smithy.api#documentation" => "<p>A list of predecessors to this job run.</p>"}))
    JobRun.add_member(:allocated_capacity, Smithy::Schema::Shapes::ShapeRef.new(shape: IntegerValue, location_name: 'AllocatedCapacity', traits: {"smithy.api#default" => 0, "smithy.api#deprecated" => {"message" => "This property is deprecated, use MaxCapacity instead."}, "smithy.api#documentation" => "<p>This field is deprecated. Use <code>MaxCapacity</code> instead.</p>\n         <p>The number of Glue data processing units (DPUs) allocated to this JobRun.\n      From 2 to 100 DPUs can be allocated; the default is 10. A DPU is a relative measure\n      of processing power that consists of 4 vCPUs of compute capacity and 16 GB of memory.\n      For more information, see the <a href=\"https://aws.amazon.com/glue/pricing/\">Glue\n        pricing page</a>.</p>"}))
    JobRun.add_member(:execution_time, Smithy::Schema::Shapes::ShapeRef.new(shape: ExecutionTime, location_name: 'ExecutionTime', traits: {"smithy.api#default" => 0, "smithy.api#documentation" => "<p>The amount of time (in seconds) that the job run consumed resources.</p>"}))
    JobRun.add_member(:timeout, Smithy::Schema::Shapes::ShapeRef.new(shape: Timeout, location_name: 'Timeout', traits: {"smithy.api#documentation" => "<p>The <code>JobRun</code> timeout in minutes. This is the maximum time that a job run can\n      consume resources before it is terminated and enters <code>TIMEOUT</code> status. This value overrides the timeout value set in the parent job.</p>\n         <p>Jobs must have timeout values less than 7 days or 10080 minutes. Otherwise, the jobs will throw an exception.</p>\n         <p>When the value is left blank, the timeout is defaulted to 2880 minutes.</p>\n         <p>Any existing Glue jobs that had a timeout value greater than 7 days will be defaulted to 7 days. For instance if you have specified a timeout of 20 days for a batch job, it will be stopped on the 7th day.</p>\n         <p>For streaming jobs, if you have set up a maintenance window, it will be restarted during the maintenance window after 7 days.</p>"}))
    JobRun.add_member(:max_capacity, Smithy::Schema::Shapes::ShapeRef.new(shape: NullableDouble, location_name: 'MaxCapacity', traits: {"smithy.api#documentation" => "<p>For Glue version 1.0 or earlier jobs, using the standard worker type, the number of\n      Glue data processing units (DPUs) that can be allocated when this job runs. A DPU is\n      a relative measure of processing power that consists of 4 vCPUs of compute capacity and 16 GB\n      of memory. For more information, see the <a href=\"https://aws.amazon.com/glue/pricing/\">\n        Glue pricing page</a>.</p>\n         <p>For Glue version 2.0+ jobs, you cannot specify a <code>Maximum capacity</code>.\n      Instead, you should specify a <code>Worker type</code> and the <code>Number of workers</code>.</p>\n         <p>Do not set <code>MaxCapacity</code> if using <code>WorkerType</code> and <code>NumberOfWorkers</code>.</p>\n         <p>The value that can be allocated for <code>MaxCapacity</code> depends on whether you are\n      running a Python shell job, an Apache Spark ETL job, or an Apache Spark streaming ETL\n      job:</p>\n         <ul>\n            <li>\n               <p>When you specify a Python shell job (<code>JobCommand.Name</code>=\"pythonshell\"), you can\n          allocate either 0.0625 or 1 DPU. The default is 0.0625 DPU.</p>\n            </li>\n            <li>\n               <p>When you specify an Apache Spark ETL job (<code>JobCommand.Name</code>=\"glueetl\") or Apache \n        Spark streaming ETL job (<code>JobCommand.Name</code>=\"gluestreaming\"), you can allocate from 2 to 100 DPUs. \n        The default is 10 DPUs. This job type cannot have a fractional DPU allocation.</p>\n            </li>\n         </ul>"}))
    JobRun.add_member(:worker_type, Smithy::Schema::Shapes::ShapeRef.new(shape: WorkerType, location_name: 'WorkerType', traits: {"smithy.api#documentation" => "<p>The type of predefined worker that is allocated when a job runs. Accepts a value of\n          G.1X, G.2X, G.4X, G.8X or G.025X for Spark jobs. Accepts the value Z.2X for Ray jobs.</p>\n         <ul>\n            <li>\n               <p>For the <code>G.1X</code> worker type, each worker maps to 1 DPU (4 vCPUs, 16 GB of memory) with 94GB disk, and provides 1 executor per worker. We recommend this worker type for workloads such as data transforms, joins, and queries, to offers a scalable and cost effective way to run most jobs.</p>\n            </li>\n            <li>\n               <p>For the <code>G.2X</code> worker type, each worker maps to 2 DPU (8 vCPUs, 32 GB of memory) with 138GB disk, and provides 1 executor per worker. We recommend this worker type for workloads such as data transforms, joins, and queries, to offers a scalable and cost effective way to run most jobs.</p>\n            </li>\n            <li>\n               <p>For the <code>G.4X</code> worker type, each worker maps to 4 DPU (16 vCPUs, 64 GB of memory) with 256GB disk, and provides 1 executor per worker. We recommend this worker type for jobs whose workloads contain your most demanding transforms, aggregations, joins, and queries. This worker type is available only for Glue version 3.0 or later Spark ETL jobs in the following Amazon Web Services Regions: US East (Ohio), US East (N. Virginia), US West (Oregon), Asia Pacific (Singapore), Asia Pacific (Sydney), Asia Pacific (Tokyo), Canada (Central), Europe (Frankfurt), Europe (Ireland), and Europe (Stockholm).</p>\n            </li>\n            <li>\n               <p>For the <code>G.8X</code> worker type, each worker maps to 8 DPU (32 vCPUs, 128 GB of memory) with 512GB disk, and provides 1 executor per worker. We recommend this worker type for jobs whose workloads contain your most demanding transforms, aggregations, joins, and queries. This worker type is available only for Glue version 3.0 or later Spark ETL jobs, in the same Amazon Web Services Regions as supported for the <code>G.4X</code> worker type.</p>\n            </li>\n            <li>\n               <p>For the <code>G.025X</code> worker type, each worker maps to 0.25 DPU (2 vCPUs, 4 GB of memory) with 84GB disk, and provides 1 executor per worker. We recommend this worker type for low volume streaming jobs. This worker type is only available for Glue version 3.0 or later streaming jobs.</p>\n            </li>\n            <li>\n               <p>For the <code>Z.2X</code> worker type, each worker maps to 2 M-DPU (8vCPUs, 64 GB of memory) with 128 GB disk, and provides up to 8 Ray workers based on the autoscaler.</p>\n            </li>\n         </ul>"}))
    JobRun.add_member(:number_of_workers, Smithy::Schema::Shapes::ShapeRef.new(shape: NullableInteger, location_name: 'NumberOfWorkers', traits: {"smithy.api#documentation" => "<p>The number of workers of a defined <code>workerType</code> that are allocated when a job runs.</p>"}))
    JobRun.add_member(:security_configuration, Smithy::Schema::Shapes::ShapeRef.new(shape: NameString, location_name: 'SecurityConfiguration', traits: {"smithy.api#documentation" => "<p>The name of the <code>SecurityConfiguration</code> structure to be used with this job\n      run.</p>"}))
    JobRun.add_member(:log_group_name, Smithy::Schema::Shapes::ShapeRef.new(shape: GenericString, location_name: 'LogGroupName', traits: {"smithy.api#documentation" => "<p>The name of the log group for secure logging that can be server-side encrypted in Amazon\n      CloudWatch using KMS. This name can be <code>/aws-glue/jobs/</code>, in which case the\n      default encryption is <code>NONE</code>. If you add a role name and\n      <code>SecurityConfiguration</code> name (in other words,\n      <code>/aws-glue/jobs-yourRoleName-yourSecurityConfigurationName/</code>), then that security\n      configuration is used to encrypt the log group.</p>"}))
    JobRun.add_member(:notification_property, Smithy::Schema::Shapes::ShapeRef.new(shape: NotificationProperty, location_name: 'NotificationProperty', traits: {"smithy.api#documentation" => "<p>Specifies configuration properties of a job run notification.</p>"}))
    JobRun.add_member(:glue_version, Smithy::Schema::Shapes::ShapeRef.new(shape: GlueVersionString, location_name: 'GlueVersion', traits: {"smithy.api#documentation" => "<p>In Spark jobs, <code>GlueVersion</code> determines the versions of Apache Spark and Python\n      that Glue available in a job. The Python version indicates the version\n      supported for jobs of type Spark. </p>\n         <p>Ray jobs should set <code>GlueVersion</code> to <code>4.0</code> or greater. However,\n    the versions of Ray, Python and additional libraries available in your Ray job are determined\n    by the <code>Runtime</code> parameter of the Job command.</p>\n         <p>For more information about the available Glue versions and corresponding\n      Spark and Python versions, see <a href=\"https://docs.aws.amazon.com/glue/latest/dg/add-job.html\">Glue version</a> in the developer\n      guide.</p>\n         <p>Jobs that are created without specifying a Glue version default to Glue 0.9.</p>"}))
    JobRun.add_member(:dpu_seconds, Smithy::Schema::Shapes::ShapeRef.new(shape: NullableDouble, location_name: 'DPUSeconds', traits: {"smithy.api#documentation" => "<p>This field can be set for either job runs with execution class <code>FLEX</code> or when Auto Scaling is enabled, and represents the total time each executor ran during the lifecycle of a job run in seconds, multiplied by a DPU factor (1 for <code>G.1X</code>, 2 for <code>G.2X</code>, or 0.25 for <code>G.025X</code> workers). This value may be different than the <code>executionEngineRuntime</code> * <code>MaxCapacity</code> as in the case of Auto Scaling jobs, as the number of executors running at a given time may be less than the <code>MaxCapacity</code>. Therefore, it is possible that the value of <code>DPUSeconds</code> is less than <code>executionEngineRuntime</code> * <code>MaxCapacity</code>.</p>"}))
    JobRun.add_member(:execution_class, Smithy::Schema::Shapes::ShapeRef.new(shape: ExecutionClass, location_name: 'ExecutionClass', traits: {"smithy.api#documentation" => "<p>Indicates whether the job is run with a standard or flexible execution class. The standard execution-class is ideal for time-sensitive workloads that require fast job startup and dedicated resources.</p>\n         <p>The flexible execution class is appropriate for time-insensitive jobs whose start and completion times may vary. </p>\n         <p>Only jobs with Glue version 3.0 and above and command type <code>glueetl</code> will be allowed to set <code>ExecutionClass</code> to <code>FLEX</code>. The flexible execution class is available for Spark jobs.</p>"}))
    JobRun.add_member(:maintenance_window, Smithy::Schema::Shapes::ShapeRef.new(shape: MaintenanceWindow, location_name: 'MaintenanceWindow', traits: {"smithy.api#documentation" => "<p>This field specifies a day of the week and hour for a maintenance window for streaming jobs. Glue periodically performs maintenance activities. During these maintenance windows, Glue will need to restart your streaming jobs.</p>\n         <p>Glue will restart the job within 3 hours of the specified maintenance window. For instance, if you set up the maintenance window for Monday at 10:00AM GMT, your jobs will be restarted between 10:00AM GMT to 1:00PM GMT.</p>"}))
    JobRun.add_member(:profile_name, Smithy::Schema::Shapes::ShapeRef.new(shape: NameString, location_name: 'ProfileName', traits: {"smithy.api#documentation" => "<p>The name of an Glue usage profile associated with the job run.</p>"}))
    JobRun.add_member(:state_detail, Smithy::Schema::Shapes::ShapeRef.new(shape: OrchestrationMessageString, location_name: 'StateDetail', traits: {"smithy.api#documentation" => "<p>This field holds details that pertain to the state of a job run. The field is nullable.</p>\n         <p>For example, when a job run is in a WAITING state as a result of job run queuing, the field has the reason why the job run is in that state.</p>"}))
    JobRun.add_member(:execution_role_session_policy, Smithy::Schema::Shapes::ShapeRef.new(shape: OrchestrationPolicyJsonString, location_name: 'ExecutionRoleSessionPolicy', traits: {"smithy.api#documentation" => "<p>This inline session policy to the StartJobRun API allows you to dynamically restrict the permissions of the specified \n      execution role for the scope of the job, without requiring the creation of additional IAM roles.</p>"}))
    JobRun.type = Types::JobRun
    JobRunList.member = Smithy::Schema::Shapes::ShapeRef.new(shape: JobRun)
    JobRunState.add_member(:starting, Smithy::Schema::Shapes::ShapeRef.new(shape: Smithy::Schema::Shapes::Prelude::Unit, location_name: 'STARTING', traits: {"smithy.api#enumValue" => "STARTING"}))
    JobRunState.add_member(:running, Smithy::Schema::Shapes::ShapeRef.new(shape: Smithy::Schema::Shapes::Prelude::Unit, location_name: 'RUNNING', traits: {"smithy.api#enumValue" => "RUNNING"}))
    JobRunState.add_member(:stopping, Smithy::Schema::Shapes::ShapeRef.new(shape: Smithy::Schema::Shapes::Prelude::Unit, location_name: 'STOPPING', traits: {"smithy.api#enumValue" => "STOPPING"}))
    JobRunState.add_member(:stopped, Smithy::Schema::Shapes::ShapeRef.new(shape: Smithy::Schema::Shapes::Prelude::Unit, location_name: 'STOPPED', traits: {"smithy.api#enumValue" => "STOPPED"}))
    JobRunState.add_member(:succeeded, Smithy::Schema::Shapes::ShapeRef.new(shape: Smithy::Schema::Shapes::Prelude::Unit, location_name: 'SUCCEEDED', traits: {"smithy.api#enumValue" => "SUCCEEDED"}))
    JobRunState.add_member(:failed, Smithy::Schema::Shapes::ShapeRef.new(shape: Smithy::Schema::Shapes::Prelude::Unit, location_name: 'FAILED', traits: {"smithy.api#enumValue" => "FAILED"}))
    JobRunState.add_member(:timeout, Smithy::Schema::Shapes::ShapeRef.new(shape: Smithy::Schema::Shapes::Prelude::Unit, location_name: 'TIMEOUT', traits: {"smithy.api#enumValue" => "TIMEOUT"}))
    JobRunState.add_member(:error, Smithy::Schema::Shapes::ShapeRef.new(shape: Smithy::Schema::Shapes::Prelude::Unit, location_name: 'ERROR', traits: {"smithy.api#enumValue" => "ERROR"}))
    JobRunState.add_member(:waiting, Smithy::Schema::Shapes::ShapeRef.new(shape: Smithy::Schema::Shapes::Prelude::Unit, location_name: 'WAITING', traits: {"smithy.api#enumValue" => "WAITING"}))
    JobRunState.add_member(:expired, Smithy::Schema::Shapes::ShapeRef.new(shape: Smithy::Schema::Shapes::Prelude::Unit, location_name: 'EXPIRED', traits: {"smithy.api#enumValue" => "EXPIRED"}))
    JobUpdate.add_member(:job_mode, Smithy::Schema::Shapes::ShapeRef.new(shape: JobMode, location_name: 'JobMode', traits: {"smithy.api#documentation" => "<p>A mode that describes how a job was created. Valid values are:</p>\n         <ul>\n            <li>\n               <p>\n                  <code>SCRIPT</code> - The job was created using the Glue Studio script editor.</p>\n            </li>\n            <li>\n               <p>\n                  <code>VISUAL</code> - The job was created using the Glue Studio visual editor.</p>\n            </li>\n            <li>\n               <p>\n                  <code>NOTEBOOK</code> - The job was created using an interactive sessions notebook.</p>\n            </li>\n         </ul>\n         <p>When the <code>JobMode</code> field is missing or null, <code>SCRIPT</code> is assigned as the default value.</p>"}))
    JobUpdate.add_member(:job_run_queuing_enabled, Smithy::Schema::Shapes::ShapeRef.new(shape: NullableBoolean, location_name: 'JobRunQueuingEnabled', traits: {"smithy.api#documentation" => "<p>Specifies whether job run queuing is enabled for the job runs for this job.</p>\n         <p>A value of true means job run queuing is enabled for the job runs. If false or not populated, the job runs will not be considered for queueing.</p>\n         <p>If this field does not match the value set in the job run, then the value from the job run field will be used.</p>"}))
    JobUpdate.add_member(:description, Smithy::Schema::Shapes::ShapeRef.new(shape: DescriptionString, location_name: 'Description', traits: {"smithy.api#documentation" => "<p>Description of the job being defined.</p>"}))
    JobUpdate.add_member(:log_uri, Smithy::Schema::Shapes::ShapeRef.new(shape: UriString, location_name: 'LogUri', traits: {"smithy.api#documentation" => "<p>This field is reserved for future use.</p>"}))
    JobUpdate.add_member(:role, Smithy::Schema::Shapes::ShapeRef.new(shape: RoleString, location_name: 'Role', traits: {"smithy.api#documentation" => "<p>The name or Amazon Resource Name (ARN) of the IAM role associated with this job\n      (required).</p>"}))
    JobUpdate.add_member(:execution_property, Smithy::Schema::Shapes::ShapeRef.new(shape: ExecutionProperty, location_name: 'ExecutionProperty', traits: {"smithy.api#documentation" => "<p>An <code>ExecutionProperty</code> specifying the maximum number of concurrent runs allowed\n      for this job.</p>"}))
    JobUpdate.add_member(:command, Smithy::Schema::Shapes::ShapeRef.new(shape: JobCommand, location_name: 'Command', traits: {"smithy.api#documentation" => "<p>The <code>JobCommand</code> that runs this job (required).</p>"}))
    JobUpdate.add_member(:default_arguments, Smithy::Schema::Shapes::ShapeRef.new(shape: GenericMap, location_name: 'DefaultArguments', traits: {"smithy.api#documentation" => "<p>The default arguments for every run of this job, specified as name-value pairs.</p>\n         <p>You can specify arguments here that your own job-execution script\n      consumes, as well as arguments that Glue itself consumes.</p>\n         <p>Job arguments may be logged. Do not pass plaintext secrets as arguments. Retrieve secrets\n      from a Glue Connection, Secrets Manager or other secret management\n      mechanism if you intend to keep them within the Job. </p>\n         <p>For information about how to specify and consume your own Job arguments, see the <a href=\"https://docs.aws.amazon.com/glue/latest/dg/aws-glue-programming-python-calling.html\">Calling Glue APIs in Python</a> topic in the developer guide.</p>\n         <p>For information about the arguments you can provide to this field when configuring Spark jobs,\n     see the <a href=\"https://docs.aws.amazon.com/glue/latest/dg/aws-glue-programming-etl-glue-arguments.html\">Special Parameters Used by Glue</a> topic in the developer guide.</p>\n         <p>For information about the arguments you can provide to this field when configuring Ray\n      jobs, see <a href=\"https://docs.aws.amazon.com/glue/latest/dg/author-job-ray-job-parameters.html\">Using\n      job parameters in Ray jobs</a> in the developer guide.</p>"}))
    JobUpdate.add_member(:non_overridable_arguments, Smithy::Schema::Shapes::ShapeRef.new(shape: GenericMap, location_name: 'NonOverridableArguments', traits: {"smithy.api#documentation" => "<p>Arguments for this job that are not overridden when providing job arguments\n      in a job run, specified as name-value pairs.</p>"}))
    JobUpdate.add_member(:connections, Smithy::Schema::Shapes::ShapeRef.new(shape: ConnectionsList, location_name: 'Connections', traits: {"smithy.api#documentation" => "<p>The connections used for this job.</p>"}))
    JobUpdate.add_member(:max_retries, Smithy::Schema::Shapes::ShapeRef.new(shape: MaxRetries, location_name: 'MaxRetries', traits: {"smithy.api#default" => 0, "smithy.api#documentation" => "<p>The maximum number of times to retry this job if it fails.</p>"}))
    JobUpdate.add_member(:allocated_capacity, Smithy::Schema::Shapes::ShapeRef.new(shape: IntegerValue, location_name: 'AllocatedCapacity', traits: {"smithy.api#default" => 0, "smithy.api#deprecated" => {"message" => "This property is deprecated, use MaxCapacity instead."}, "smithy.api#documentation" => "<p>This field is deprecated. Use <code>MaxCapacity</code> instead.</p>\n         <p>The number of Glue data processing units (DPUs) to allocate to this job. You can\n      allocate a minimum of 2 DPUs; the default is 10. A DPU is a relative measure of processing\n      power that consists of 4 vCPUs of compute capacity and 16 GB of memory. For more information,\n      see the <a href=\"https://aws.amazon.com/glue/pricing/\">Glue pricing\n      page</a>.</p>"}))
    JobUpdate.add_member(:timeout, Smithy::Schema::Shapes::ShapeRef.new(shape: Timeout, location_name: 'Timeout', traits: {"smithy.api#documentation" => "<p>The job timeout in minutes.  This is the maximum time that a job run\n      can consume resources before it is terminated and enters <code>TIMEOUT</code>\n      status.</p>\n         <p>Jobs must have timeout values less than 7 days or 10080 minutes. Otherwise, the jobs will throw an exception.</p>\n         <p>When the value is left blank, the timeout is defaulted to 2880 minutes.</p>\n         <p>Any existing Glue jobs that had a timeout value greater than 7 days will be defaulted to 7 days. For instance if you have specified a timeout of 20 days for a batch job, it will be stopped on the 7th day.</p>\n         <p>For streaming jobs, if you have set up a maintenance window, it will be restarted during the maintenance window after 7 days.</p>"}))
    JobUpdate.add_member(:max_capacity, Smithy::Schema::Shapes::ShapeRef.new(shape: NullableDouble, location_name: 'MaxCapacity', traits: {"smithy.api#documentation" => "<p>For Glue version 1.0 or earlier jobs, using the standard worker type, the number of\n      Glue data processing units (DPUs) that can be allocated when this job runs. A DPU is\n      a relative measure of processing power that consists of 4 vCPUs of compute capacity and 16 GB\n      of memory. For more information, see the <a href=\"https://aws.amazon.com/glue/pricing/\">\n      Glue pricing page</a>.</p>\n         <p>For Glue version 2.0+ jobs, you cannot specify a <code>Maximum capacity</code>.\n      Instead, you should specify a <code>Worker type</code> and the <code>Number of workers</code>.</p>\n         <p>Do not set <code>MaxCapacity</code> if using <code>WorkerType</code> and <code>NumberOfWorkers</code>.</p>\n         <p>The value that can be allocated for <code>MaxCapacity</code> depends on whether you are\n      running a Python shell job, an Apache Spark ETL job, or an Apache Spark streaming ETL\n      job:</p>\n         <ul>\n            <li>\n               <p>When you specify a Python shell job (<code>JobCommand.Name</code>=\"pythonshell\"), you can\n          allocate either 0.0625 or 1 DPU. The default is 0.0625 DPU.</p>\n            </li>\n            <li>\n               <p>When you specify an Apache Spark ETL job (<code>JobCommand.Name</code>=\"glueetl\") or Apache \n        Spark streaming ETL job (<code>JobCommand.Name</code>=\"gluestreaming\"), you can allocate from 2 to 100 DPUs. \n        The default is 10 DPUs. This job type cannot have a fractional DPU allocation.</p>\n            </li>\n         </ul>"}))
    JobUpdate.add_member(:worker_type, Smithy::Schema::Shapes::ShapeRef.new(shape: WorkerType, location_name: 'WorkerType', traits: {"smithy.api#documentation" => "<p>The type of predefined worker that is allocated when a job runs. Accepts a value of\n      G.1X, G.2X, G.4X, G.8X or G.025X for Spark jobs. Accepts the value Z.2X for Ray jobs. For more information, see \n      <a href=\"https://docs.aws.amazon.com/glue/latest/dg/add-job.html#create-job\">Defining job properties for Spark jobs   \n      </a>\n         </p>"}))
    JobUpdate.add_member(:number_of_workers, Smithy::Schema::Shapes::ShapeRef.new(shape: NullableInteger, location_name: 'NumberOfWorkers', traits: {"smithy.api#documentation" => "<p>The number of workers of a defined <code>workerType</code> that are allocated when a job runs.</p>"}))
    JobUpdate.add_member(:security_configuration, Smithy::Schema::Shapes::ShapeRef.new(shape: NameString, location_name: 'SecurityConfiguration', traits: {"smithy.api#documentation" => "<p>The name of the <code>SecurityConfiguration</code> structure to be used with this\n      job.</p>"}))
    JobUpdate.add_member(:notification_property, Smithy::Schema::Shapes::ShapeRef.new(shape: NotificationProperty, location_name: 'NotificationProperty', traits: {"smithy.api#documentation" => "<p>Specifies the configuration properties of a job notification.</p>"}))
    JobUpdate.add_member(:glue_version, Smithy::Schema::Shapes::ShapeRef.new(shape: GlueVersionString, location_name: 'GlueVersion', traits: {"smithy.api#documentation" => "<p>In Spark jobs, <code>GlueVersion</code> determines the versions of Apache Spark and Python\n      that Glue available in a job. The Python version indicates the version\n      supported for jobs of type Spark. </p>\n         <p>Ray jobs should set <code>GlueVersion</code> to <code>4.0</code> or greater. However,\n    the versions of Ray, Python and additional libraries available in your Ray job are determined\n    by the <code>Runtime</code> parameter of the Job command.</p>\n         <p>For more information about the available Glue versions and corresponding\n      Spark and Python versions, see <a href=\"https://docs.aws.amazon.com/glue/latest/dg/add-job.html\">Glue version</a> in the developer\n      guide.</p>\n         <p>Jobs that are created without specifying a Glue version default to Glue 0.9.</p>"}))
    JobUpdate.add_member(:code_gen_configuration_nodes, Smithy::Schema::Shapes::ShapeRef.new(shape: CodeGenConfigurationNodes, location_name: 'CodeGenConfigurationNodes', traits: {"smithy.api#documentation" => "<p>The representation of a directed acyclic graph on which both the Glue Studio visual component and Glue Studio code generation is based.</p>"}))
    JobUpdate.add_member(:execution_class, Smithy::Schema::Shapes::ShapeRef.new(shape: ExecutionClass, location_name: 'ExecutionClass', traits: {"smithy.api#documentation" => "<p>Indicates whether the job is run with a standard or flexible execution class. The standard execution-class is ideal for time-sensitive workloads that require fast job startup and dedicated resources.</p>\n         <p>The flexible execution class is appropriate for time-insensitive jobs whose start and completion times may vary. </p>\n         <p>Only jobs with Glue version 3.0 and above and command type <code>glueetl</code> will be allowed to set <code>ExecutionClass</code> to <code>FLEX</code>. The flexible execution class is available for Spark jobs.</p>"}))
    JobUpdate.add_member(:source_control_details, Smithy::Schema::Shapes::ShapeRef.new(shape: SourceControlDetails, location_name: 'SourceControlDetails', traits: {"smithy.api#documentation" => "<p>The details for a source control configuration for a job, allowing synchronization of job artifacts to or from a remote repository.</p>"}))
    JobUpdate.add_member(:maintenance_window, Smithy::Schema::Shapes::ShapeRef.new(shape: MaintenanceWindow, location_name: 'MaintenanceWindow', traits: {"smithy.api#documentation" => "<p>This field specifies a day of the week and hour for a maintenance window for streaming jobs. Glue periodically performs maintenance activities. During these maintenance windows, Glue will need to restart your streaming jobs.</p>\n         <p>Glue will restart the job within 3 hours of the specified maintenance window. For instance, if you set up the maintenance window for Monday at 10:00AM GMT, your jobs will be restarted between 10:00AM GMT to 1:00PM GMT.</p>"}))
    JobUpdate.type = Types::JobUpdate
    Join.add_member(:name, Smithy::Schema::Shapes::ShapeRef.new(shape: NodeName, location_name: 'Name', traits: {"smithy.api#documentation" => "<p>The name of the transform node.</p>", "smithy.api#required" => {}}))
