    JsonClassifier.add_member(:creation_time, Smithy::Schema::Shapes::ShapeRef.new(shape: Timestamp, location_name: 'CreationTime', traits: {"smithy.api#documentation" => "<p>The time that this classifier was registered.</p>"}))
    JsonClassifier.add_member(:last_updated, Smithy::Schema::Shapes::ShapeRef.new(shape: Timestamp, location_name: 'LastUpdated', traits: {"smithy.api#documentation" => "<p>The time that this classifier was last updated.</p>"}))
    JsonClassifier.add_member(:version, Smithy::Schema::Shapes::ShapeRef.new(shape: VersionId, location_name: 'Version', traits: {"smithy.api#default" => 0, "smithy.api#documentation" => "<p>The version of this classifier.</p>"}))
    JsonClassifier.add_member(:json_path, Smithy::Schema::Shapes::ShapeRef.new(shape: JsonPath, location_name: 'JsonPath', traits: {"smithy.api#documentation" => "<p>A <code>JsonPath</code> string defining the JSON data for the classifier to classify.\n      Glue supports a subset of JsonPath, as described in <a href=\"https://docs.aws.amazon.com/glue/latest/dg/custom-classifier.html#custom-classifier-json\">Writing JsonPath Custom Classifiers</a>.</p>", "smithy.api#required" => {}}))
