    KafkaStreamingSourceOptions.add_member(:bootstrap_servers, Smithy::Schema::Shapes::ShapeRef.new(shape: EnclosedInStringProperty, location_name: 'BootstrapServers', traits: {"smithy.api#documentation" => "<p>A list of bootstrap server URLs, for example, as <code>b-1.vpc-test-2.o4q88o.c6.kafka.us-east-1.amazonaws.com:9094</code>. This option must be specified in the API call or defined in the table metadata in the Data Catalog.</p>"}))
    KafkaStreamingSourceOptions.add_member(:security_protocol, Smithy::Schema::Shapes::ShapeRef.new(shape: EnclosedInStringProperty, location_name: 'SecurityProtocol', traits: {"smithy.api#documentation" => "<p>The protocol used to communicate with brokers. The possible values are <code>\"SSL\"</code> or <code>\"PLAINTEXT\"</code>.</p>"}))
    KafkaStreamingSourceOptions.add_member(:connection_name, Smithy::Schema::Shapes::ShapeRef.new(shape: EnclosedInStringProperty, location_name: 'ConnectionName', traits: {"smithy.api#documentation" => "<p>The name of the connection.</p>"}))
    KafkaStreamingSourceOptions.add_member(:topic_name, Smithy::Schema::Shapes::ShapeRef.new(shape: EnclosedInStringProperty, location_name: 'TopicName', traits: {"smithy.api#documentation" => "<p>The topic name as specified in Apache Kafka. You must specify at least one of <code>\"topicName\"</code>, <code>\"assign\"</code> or <code>\"subscribePattern\"</code>.</p>"}))
    KafkaStreamingSourceOptions.add_member(:assign, Smithy::Schema::Shapes::ShapeRef.new(shape: EnclosedInStringProperty, location_name: 'Assign', traits: {"smithy.api#documentation" => "<p>The specific <code>TopicPartitions</code> to consume. You must specify at least one of <code>\"topicName\"</code>, <code>\"assign\"</code> or <code>\"subscribePattern\"</code>.</p>"}))
    KafkaStreamingSourceOptions.add_member(:subscribe_pattern, Smithy::Schema::Shapes::ShapeRef.new(shape: EnclosedInStringProperty, location_name: 'SubscribePattern', traits: {"smithy.api#documentation" => "<p>A Java regex string that identifies the topic list to subscribe to. You must specify at least one of <code>\"topicName\"</code>, <code>\"assign\"</code> or <code>\"subscribePattern\"</code>.</p>"}))
    KafkaStreamingSourceOptions.add_member(:classification, Smithy::Schema::Shapes::ShapeRef.new(shape: EnclosedInStringProperty, location_name: 'Classification', traits: {"smithy.api#documentation" => "<p>An optional classification.</p>"}))
    KafkaStreamingSourceOptions.add_member(:delimiter, Smithy::Schema::Shapes::ShapeRef.new(shape: EnclosedInStringProperty, location_name: 'Delimiter', traits: {"smithy.api#documentation" => "<p>Specifies the delimiter character.</p>"}))
    KafkaStreamingSourceOptions.add_member(:starting_offsets, Smithy::Schema::Shapes::ShapeRef.new(shape: EnclosedInStringProperty, location_name: 'StartingOffsets', traits: {"smithy.api#documentation" => "<p>The starting position in the Kafka topic to read data from. The possible values are <code>\"earliest\"</code> or <code>\"latest\"</code>. The default value is <code>\"latest\"</code>.</p>"}))
    KafkaStreamingSourceOptions.add_member(:ending_offsets, Smithy::Schema::Shapes::ShapeRef.new(shape: EnclosedInStringProperty, location_name: 'EndingOffsets', traits: {"smithy.api#documentation" => "<p>The end point when a batch query is ended. Possible values are either <code>\"latest\"</code> or a JSON string that specifies an ending offset for each <code>TopicPartition</code>.</p>"}))
    KafkaStreamingSourceOptions.add_member(:poll_timeout_ms, Smithy::Schema::Shapes::ShapeRef.new(shape: BoxedNonNegativeLong, location_name: 'PollTimeoutMs', traits: {"smithy.api#documentation" => "<p>The timeout in milliseconds to poll data from Kafka in Spark job executors. The default value is <code>512</code>.</p>"}))
    KafkaStreamingSourceOptions.add_member(:num_retries, Smithy::Schema::Shapes::ShapeRef.new(shape: BoxedNonNegativeInt, location_name: 'NumRetries', traits: {"smithy.api#documentation" => "<p>The number of times to retry before failing to fetch Kafka offsets. The default value is <code>3</code>.</p>"}))
    KafkaStreamingSourceOptions.add_member(:retry_interval_ms, Smithy::Schema::Shapes::ShapeRef.new(shape: BoxedNonNegativeLong, location_name: 'RetryIntervalMs', traits: {"smithy.api#documentation" => "<p>The time in milliseconds to wait before retrying to fetch Kafka offsets. The default value is <code>10</code>.</p>"}))
    KafkaStreamingSourceOptions.add_member(:max_offsets_per_trigger, Smithy::Schema::Shapes::ShapeRef.new(shape: BoxedNonNegativeLong, location_name: 'MaxOffsetsPerTrigger', traits: {"smithy.api#documentation" => "<p>The rate limit on the maximum number of offsets that are processed per trigger interval. The specified total number of offsets is proportionally split across <code>topicPartitions</code> of different volumes. The default value is null, which means that the consumer reads all offsets until the known latest offset.</p>"}))
    KafkaStreamingSourceOptions.add_member(:min_partitions, Smithy::Schema::Shapes::ShapeRef.new(shape: BoxedNonNegativeInt, location_name: 'MinPartitions', traits: {"smithy.api#documentation" => "<p>The desired minimum number of partitions to read from Kafka. The default value is null, which means that the number of spark partitions is equal to the number of Kafka partitions.</p>"}))
    KafkaStreamingSourceOptions.add_member(:include_headers, Smithy::Schema::Shapes::ShapeRef.new(shape: BoxedBoolean, location_name: 'IncludeHeaders', traits: {"smithy.api#documentation" => "<p>Whether to include the Kafka headers. When the option is set to \"true\", the data output will contain an additional column named \"glue_streaming_kafka_headers\" \n          with type <code>Array[Struct(key: String, value: String)]</code>. The default value is \"false\". \n      This option is available in Glue version 3.0 or later only.</p>"}))
    KafkaStreamingSourceOptions.add_member(:add_record_timestamp, Smithy::Schema::Shapes::ShapeRef.new(shape: EnclosedInStringProperty, location_name: 'AddRecordTimestamp', traits: {"smithy.api#documentation" => "<p>When this option is set to 'true', the data output will contain an additional column named \"__src_timestamp\" that indicates the time when the corresponding record received by the topic. The default value is 'false'. This option is supported in Glue  version 4.0 or later.</p>"}))
    KafkaStreamingSourceOptions.add_member(:emit_consumer_lag_metrics, Smithy::Schema::Shapes::ShapeRef.new(shape: EnclosedInStringProperty, location_name: 'EmitConsumerLagMetrics', traits: {"smithy.api#documentation" => "<p>When this option is set to 'true', for each batch, it will emit the metrics for the duration between the oldest record received by the topic and the time it arrives in Glue to CloudWatch. The metric's name is \"glue.driver.streaming.maxConsumerLagInMs\". The default value is 'false'. This option is supported in Glue version 4.0 or later.</p>"}))
    KafkaStreamingSourceOptions.add_member(:starting_timestamp, Smithy::Schema::Shapes::ShapeRef.new(shape: Iso8601DateTime, location_name: 'StartingTimestamp', traits: {"smithy.api#documentation" => "<p>The timestamp of the record in the Kafka topic to start reading data from. The possible values are a timestamp string in UTC format of the pattern <code>yyyy-mm-ddTHH:MM:SSZ</code> (where Z represents a UTC timezone offset with a +/-. For example: \"2023-04-04T08:00:00+08:00\"). </p>\n         <p>Only one of <code>StartingTimestamp</code> or <code>StartingOffsets</code> must be set.</p>"}))
    KafkaStreamingSourceOptions.type = Types::KafkaStreamingSourceOptions
