    KeySchemaElement.add_member(:name, Smithy::Schema::Shapes::ShapeRef.new(shape: NameString, location_name: 'Name', traits: {"smithy.api#documentation" => "<p>The name of a partition key.</p>", "smithy.api#required" => {}}))
    KeySchemaElement.add_member(:type, Smithy::Schema::Shapes::ShapeRef.new(shape: ColumnTypeString, location_name: 'Type', traits: {"smithy.api#documentation" => "<p>The type of a partition key.</p>", "smithy.api#required" => {}}))
