    KinesisStreamingSourceOptions.add_member(:endpoint_url, Smithy::Schema::Shapes::ShapeRef.new(shape: EnclosedInStringProperty, location_name: 'EndpointUrl', traits: {"smithy.api#documentation" => "<p>The URL of the Kinesis endpoint.</p>"}))
    KinesisStreamingSourceOptions.add_member(:stream_name, Smithy::Schema::Shapes::ShapeRef.new(shape: EnclosedInStringProperty, location_name: 'StreamName', traits: {"smithy.api#documentation" => "<p>The name of the Kinesis data stream.</p>"}))
    KinesisStreamingSourceOptions.add_member(:classification, Smithy::Schema::Shapes::ShapeRef.new(shape: EnclosedInStringProperty, location_name: 'Classification', traits: {"smithy.api#documentation" => "<p>An optional classification.</p>"}))
    KinesisStreamingSourceOptions.add_member(:delimiter, Smithy::Schema::Shapes::ShapeRef.new(shape: EnclosedInStringProperty, location_name: 'Delimiter', traits: {"smithy.api#documentation" => "<p>Specifies the delimiter character.</p>"}))
    KinesisStreamingSourceOptions.add_member(:starting_position, Smithy::Schema::Shapes::ShapeRef.new(shape: StartingPosition, location_name: 'StartingPosition', traits: {"smithy.api#documentation" => "<p>The starting position in the Kinesis data stream to read data from. The possible values are <code>\"latest\"</code>, <code>\"trim_horizon\"</code>, <code>\"earliest\"</code>, or a timestamp string in UTC format in the pattern <code>yyyy-mm-ddTHH:MM:SSZ</code> (where <code>Z</code> represents a UTC timezone offset with a +/-. For example: \"2023-04-04T08:00:00-04:00\"). The default value is <code>\"latest\"</code>.</p>\n         <p>Note: Using a value that is a timestamp string in UTC format for \"startingPosition\" is supported only for Glue version 4.0 or later.</p>"}))
    KinesisStreamingSourceOptions.add_member(:max_fetch_time_in_ms, Smithy::Schema::Shapes::ShapeRef.new(shape: BoxedNonNegativeLong, location_name: 'MaxFetchTimeInMs', traits: {"smithy.api#documentation" => "<p>The maximum time spent for the job executor to read records for the current batch from the Kinesis data stream, specified in milliseconds (ms). Multiple <code>GetRecords</code> API calls may be made within this time. The default value is <code>1000</code>.</p>"}))
    KinesisStreamingSourceOptions.add_member(:max_fetch_records_per_shard, Smithy::Schema::Shapes::ShapeRef.new(shape: BoxedNonNegativeLong, location_name: 'MaxFetchRecordsPerShard', traits: {"smithy.api#documentation" => "<p>The maximum number of records to fetch per shard in the Kinesis data stream per microbatch. Note: The client can exceed this limit if the streaming job has already read extra records from Kinesis (in the same get-records call). If <code>MaxFetchRecordsPerShard</code> needs to be strict then it needs to be a multiple of <code>MaxRecordPerRead</code>. The default value is <code>100000</code>.</p>"}))
    KinesisStreamingSourceOptions.add_member(:max_record_per_read, Smithy::Schema::Shapes::ShapeRef.new(shape: BoxedNonNegativeLong, location_name: 'MaxRecordPerRead', traits: {"smithy.api#documentation" => "<p>The maximum number of records to fetch from the Kinesis data stream in each getRecords operation. The default value is <code>10000</code>.</p>"}))
    KinesisStreamingSourceOptions.add_member(:add_idle_time_between_reads, Smithy::Schema::Shapes::ShapeRef.new(shape: BoxedBoolean, location_name: 'AddIdleTimeBetweenReads', traits: {"smithy.api#documentation" => "<p>Adds a time delay between two consecutive getRecords operations. The default value is <code>\"False\"</code>. This option is only configurable for Glue version 2.0 and above.</p>"}))
    KinesisStreamingSourceOptions.add_member(:idle_time_between_reads_in_ms, Smithy::Schema::Shapes::ShapeRef.new(shape: BoxedNonNegativeLong, location_name: 'IdleTimeBetweenReadsInMs', traits: {"smithy.api#documentation" => "<p>The minimum time delay between two consecutive getRecords operations, specified in ms. The default value is <code>1000</code>. This option is only configurable for Glue version 2.0 and above.</p>"}))
    KinesisStreamingSourceOptions.add_member(:describe_shard_interval, Smithy::Schema::Shapes::ShapeRef.new(shape: BoxedNonNegativeLong, location_name: 'DescribeShardInterval', traits: {"smithy.api#documentation" => "<p>The minimum time interval between two ListShards API calls for your script to consider resharding. The default value is <code>1s</code>.</p>"}))
    KinesisStreamingSourceOptions.add_member(:num_retries, Smithy::Schema::Shapes::ShapeRef.new(shape: BoxedNonNegativeInt, location_name: 'NumRetries', traits: {"smithy.api#documentation" => "<p>The maximum number of retries for Kinesis Data Streams API requests. The default value is <code>3</code>.</p>"}))
    KinesisStreamingSourceOptions.add_member(:retry_interval_ms, Smithy::Schema::Shapes::ShapeRef.new(shape: BoxedNonNegativeLong, location_name: 'RetryIntervalMs', traits: {"smithy.api#documentation" => "<p>The cool-off time period (specified in ms) before retrying the Kinesis Data Streams API call. The default value is <code>1000</code>.</p>"}))
    KinesisStreamingSourceOptions.add_member(:max_retry_interval_ms, Smithy::Schema::Shapes::ShapeRef.new(shape: BoxedNonNegativeLong, location_name: 'MaxRetryIntervalMs', traits: {"smithy.api#documentation" => "<p>The maximum cool-off time period (specified in ms) between two retries of a Kinesis Data Streams API call. The default value is <code>10000</code>.</p>"}))
    KinesisStreamingSourceOptions.add_member(:avoid_empty_batches, Smithy::Schema::Shapes::ShapeRef.new(shape: BoxedBoolean, location_name: 'AvoidEmptyBatches', traits: {"smithy.api#documentation" => "<p>Avoids creating an empty microbatch job by checking for unread data in the Kinesis data stream before the batch is started. The default value is <code>\"False\"</code>.</p>"}))
    KinesisStreamingSourceOptions.add_member(:stream_arn, Smithy::Schema::Shapes::ShapeRef.new(shape: EnclosedInStringProperty, location_name: 'StreamArn', traits: {"smithy.api#documentation" => "<p>The Amazon Resource Name (ARN) of the Kinesis data stream.</p>"}))
    KinesisStreamingSourceOptions.add_member(:role_arn, Smithy::Schema::Shapes::ShapeRef.new(shape: EnclosedInStringProperty, location_name: 'RoleArn', traits: {"smithy.api#documentation" => "<p>The Amazon Resource Name (ARN) of the role to assume using AWS Security Token Service (AWS STS). This role must have permissions for describe or read record operations for the Kinesis data stream. You must use this parameter when accessing a data stream in a different account. Used in conjunction with <code>\"awsSTSSessionName\"</code>.</p>"}))
    KinesisStreamingSourceOptions.add_member(:role_session_name, Smithy::Schema::Shapes::ShapeRef.new(shape: EnclosedInStringProperty, location_name: 'RoleSessionName', traits: {"smithy.api#documentation" => "<p>An identifier for the session assuming the role using AWS STS. You must use this parameter when accessing a data stream in a different account. Used in conjunction with <code>\"awsSTSRoleARN\"</code>.</p>"}))
    KinesisStreamingSourceOptions.add_member(:add_record_timestamp, Smithy::Schema::Shapes::ShapeRef.new(shape: EnclosedInStringProperty, location_name: 'AddRecordTimestamp', traits: {"smithy.api#documentation" => "<p>When this option is set to 'true', the data output will contain an additional column named \"__src_timestamp\" that indicates the time when the corresponding record received by the stream. The default value is 'false'. This option is supported in Glue version 4.0 or later.</p>"}))
    KinesisStreamingSourceOptions.add_member(:emit_consumer_lag_metrics, Smithy::Schema::Shapes::ShapeRef.new(shape: EnclosedInStringProperty, location_name: 'EmitConsumerLagMetrics', traits: {"smithy.api#documentation" => "<p>When this option is set to 'true', for each batch, it will emit the metrics for the duration between the oldest record received by the stream and the time it arrives in Glue  to CloudWatch. The metric's name is \"glue.driver.streaming.maxConsumerLagInMs\". The default value is 'false'. This option is supported in Glue version 4.0 or later.</p>"}))
    KinesisStreamingSourceOptions.add_member(:starting_timestamp, Smithy::Schema::Shapes::ShapeRef.new(shape: Iso8601DateTime, location_name: 'StartingTimestamp', traits: {"smithy.api#documentation" => "<p>The timestamp of the record in the Kinesis data stream to start reading data from. The possible values are a timestamp string in UTC format of the pattern <code>yyyy-mm-ddTHH:MM:SSZ</code> (where Z represents a UTC timezone offset with a +/-. For example: \"2023-04-04T08:00:00+08:00\"). </p>"}))
