    S3CsvSource.add_member(:exclusions, Smithy::Schema::Shapes::ShapeRef.new(shape: EnclosedInStringProperties, location_name: 'Exclusions', traits: {"smithy.api#documentation" => "<p>A string containing a JSON list of Unix-style glob patterns to exclude. For example, \"[\\\"**.pdf\\\"]\" excludes all PDF files. </p>"}))
