    S3CsvSource.add_member(:group_files, Smithy::Schema::Shapes::ShapeRef.new(shape: EnclosedInStringProperty, location_name: 'GroupFiles', traits: {"smithy.api#documentation" => "<p>Grouping files is turned on by default when the input contains more than 50,000 files. To turn on grouping with fewer than 50,000 files, set this parameter to \"inPartition\". To disable grouping when there are more than 50,000 files, set this parameter to <code>\"none\"</code>.</p>"}))
