    S3CsvSource.add_member(:separator, Smithy::Schema::Shapes::ShapeRef.new(shape: Separator, location_name: 'Separator', traits: {"smithy.api#documentation" => "<p>Specifies the delimiter character. The default is a comma: \",\", but any other character can be specified.</p>", "smithy.api#required" => {}}))
    S3CsvSource.add_member(:escaper, Smithy::Schema::Shapes::ShapeRef.new(shape: EnclosedInStringPropertyWithQuote, location_name: 'Escaper', traits: {"smithy.api#documentation" => "<p>Specifies a character to use for escaping. This option is used only when reading CSV files. The default value is <code>none</code>. If enabled, the character which immediately follows is used as-is, except for a small set of well-known escapes (<code>\\n</code>, <code>\\r</code>, <code>\\t</code>, and <code>\\0</code>).</p>"}))
    S3CsvSource.add_member(:quote_char, Smithy::Schema::Shapes::ShapeRef.new(shape: QuoteChar, location_name: 'QuoteChar', traits: {"smithy.api#documentation" => "<p>Specifies the character to use for quoting. The default is a double quote: <code>'\"'</code>. Set this to <code>-1</code> to turn off quoting entirely.</p>", "smithy.api#required" => {}}))
    S3CsvSource.add_member(:multiline, Smithy::Schema::Shapes::ShapeRef.new(shape: BoxedBoolean, location_name: 'Multiline', traits: {"smithy.api#documentation" => "<p>A Boolean value that specifies whether a single record can span multiple lines. This can occur when a field contains a quoted new-line character. You must set this option to True if any record spans multiple lines. The default value is <code>False</code>, which allows for more aggressive file-splitting during parsing.</p>"}))
    S3CsvSource.add_member(:with_header, Smithy::Schema::Shapes::ShapeRef.new(shape: BoxedBoolean, location_name: 'WithHeader', traits: {"smithy.api#documentation" => "<p>A Boolean value that specifies whether to treat the first line as a header. The default value is <code>False</code>.</p>"}))
