    S3CsvSource.add_member(:optimize_performance, Smithy::Schema::Shapes::ShapeRef.new(shape: BooleanValue, location_name: 'OptimizePerformance', traits: {"smithy.api#default" => false, "smithy.api#documentation" => "<p>A Boolean value that specifies whether to use the advanced SIMD CSV reader along with Apache Arrow based columnar memory formats. Only available in Glue version 3.0.</p>"}))
